import * as React from "react"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { formatMoney } from "../../config/pricing"
import { LEVELS, TIERS } from "../../data/plans"
import { useAuth } from "../../context/auth"
import { supabase } from "../../lib/supabase"
import * as s from "./Upsell.module.css"

/**
 * Free, Premium and Lead Generation side by side, with the way to move — FCS-100, FCS-101.
 * ============================================================================
 * Shared by every "this is part of a paid plan" screen (tracked QR codes,
 * saved invoices), because the plans are the same wherever somebody meets the
 * wall, and two copies of a price table is how they come to disagree.
 *
 * ── EVERY FACT COMES FROM THE PLAN DATA ────────────────────────────────────
 * Prices and what each plan includes are read from src/data/plans.js, the list
 * the builder's tier picker uses, so this cannot promise something the
 * checkout does not sell. The only words that belong to the screen using it
 * are the heading above the cards and the badge on the paid ones.
 *
 * ── PAYING TWICE IS NOT POSSIBLE FROM HERE ─────────────────────────────────
 * Somebody on Free is sent to Stripe Checkout. Somebody who ALREADY pays is
 * sent to Stripe's billing portal to change plan, because a second Checkout
 * would start a second subscription. The server refuses that too; this just
 * does not offer it.
 */

const RANK = { free: 0, premium: 1, leads: 2 }
const ORDER = ["free", "premium", "leads"]

const DEFAULT_FREE = ["The website builder and preview", "The invoice builder", "The QR code maker"]

/** What each plan lists. Premium and Lead Generation come straight from the plan data. */
export const featuresFor = tier => {
  if (tier === "free") return { lead: TIERS.free.tagline, items: DEFAULT_FREE }
  const premium = LEVELS.find(l => l.tier === "premium")?.items.map(i => i.label) || []
  if (tier === "premium") return { lead: "Other benefits that come with it:", items: premium }
  const leads = LEVELS.find(l => l.tier === "leads")?.items.map(i => i.label) || []
  return { lead: "Everything in Premium, plus:", items: leads }
}

/**
 * Asks the server for a Stripe address: a Checkout for somebody on Free, the
 * billing portal for somebody who already pays. Returns `{ ok, url }` or
 * `{ ok: false, message }` and never throws, because every caller has to say
 * something useful when it fails. Shared by the plan cards and the billing screen.
 */
export async function openStripe({ kind, plan, email = "", returnTo = "" }) {
  try {
    const client = supabase()
    const { data } = client ? await client.auth.getSession() : { data: null }
    const token = data?.session?.access_token

    const res = await fetch(apiUrl(kind === "portal" ? "billing-portal" : "create-checkout-session"), {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        apikey: SUPABASE_PUBLISHABLE_KEY,
        Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
      },
      body: JSON.stringify(
        kind === "portal"
          ? { origin: window.location.origin }
          : {
              plan,
              returnTo: "account",
              ...(returnTo ? { returnHash: returnTo } : {}),
              billing: { email },
              site: {},
              origin: window.location.origin,
            }
      ),
    })
    const body = await res.json().catch(() => ({}))
    if (res.ok && body.url) return { ok: true, url: body.url }
    return { ok: false, message: body.message || "That could not be opened just now. Please try again." }
  } catch {
    return { ok: false, message: "We could not reach the payment service. Check your connection and try again." }
  }
}

/**
 * `currentPlan`  "free" | "premium" | "leads"
 * `title/lead`   the heading above the cards, in the words of the screen using it
 * `badge`        the tag on each plan that includes the feature: what it unlocks HERE
 *                ("Includes QR tracking"), with a "Plus ..." line under it saying the plan
 *                also brings its other benefits, so those read as extras and not a repeat
 * `unlockedBy`   which paid plans include that feature; Premium and Lead Generation unless
 *                the screen says otherwise (the quote form is Lead Generation only)
 * `returnTo`     where Stripe sends them back: a hash on the account page
 */
const PlanPicker = ({ currentPlan = "free", title, lead, badge, returnTo = "", unlockedBy = ["premium", "leads"] }) => {
  const { user } = useAuth()
  const [busy, setBusy] = React.useState("")
  const [error, setError] = React.useState("")

  const rank = RANK[currentPlan] ?? 0
  const paying = rank > 0

  const open = async (kind, plan) => {
    setBusy(`${kind}:${plan || ""}`)
    setError("")
    const result = await openStripe({ kind, plan, email: user?.email || "", returnTo })
    if (result.ok) {
      window.location.assign(result.url)
      return
    }
    setError(result.message)
    setBusy("")
  }

  return (
    <>
      {title ? <h3 className={s.plansTitle}>{title}</h3> : null}
      {lead ? <p className={s.plansLead}>{lead}</p> : null}

      <div className={s.plans} role="list" aria-label="Plans">
        {ORDER.map(id => {
          const tier = TIERS[id]
          if (!tier) return null
          const { lead: planLead, items } = featuresFor(id)
          const here = RANK[id] === rank
          const included = RANK[id] < rank
          const upgrade = RANK[id] > rank

          return (
            <article key={id} className={s.plan} role="listitem" data-plan={id} data-current={here ? "true" : undefined}>
              <header className={s.planHead}>
                <h4 className={s.planName}>{tier.name}</h4>
                {here ? <span className={s.here}>Your plan</span> : null}
              </header>
              <p className={s.price}>
                <strong>{id === "free" ? "$0" : formatMoney(tier.amount)}</strong>
                {id === "free" ? " always" : " a month"}
              </p>
              {badge && unlockedBy.includes(id) ? (
                <>
                  <p className={s.unlocks}>{badge}</p>
                  <p className={s.alsoLine}>
                    {id === "premium"
                      ? "Plus your website and every other benefit below."
                      : "Plus everything in Premium, and the lead generation tools below."}
                  </p>
                </>
              ) : null}
              {planLead ? <p className={s.planLead}>{planLead}</p> : null}
              <ul className={s.items}>
                {items.map(item => (
                  <li key={item}>{item}</li>
                ))}
              </ul>

              <div className={s.planFoot}>
                {here ? (
                  <span className={s.note}>You are on this plan.</span>
                ) : included ? (
                  <span className={s.note}>Included in your plan.</span>
                ) : upgrade && !paying ? (
                  <button
                    type="button"
                    className={s.cta}
                    onClick={() => open("checkout", id)}
                    disabled={Boolean(busy)}
                  >
                    {busy === `checkout:${id}` ? "Opening Stripe…" : `Get ${tier.name}`}
                  </button>
                ) : upgrade ? (
                  <button
                    type="button"
                    className={s.cta}
                    onClick={() => open("portal")}
                    disabled={Boolean(busy)}
                  >
                    {busy === "portal:" ? "Opening Stripe…" : `Switch to ${tier.name}`}
                  </button>
                ) : null}
              </div>
            </article>
          )
        })}
      </div>

      {error ? (
        <p className={s.error} role="alert">
          {error}
        </p>
      ) : null}

      <p className={s.foot}>
        {paying ? (
          <>
            Already paying? Change or cancel your plan any time in{" "}
            <button type="button" className={s.link} onClick={() => open("portal")} disabled={Boolean(busy)}>
              {busy === "portal:" ? "opening Stripe…" : "Stripe’s billing portal"}
            </button>
            .
          </>
        ) : (
          <>Payment is taken by Stripe. You can cancel whenever you like, and nothing is stored here.</>
        )}
      </p>
    </>
  )
}

export default PlanPicker
