import * as React from "react"
import * as s from "./AdGallery.module.css"

/**
 * The adverts a marketer has saved, and what each one did — FCS-072.
 * ============================================================================
 * The table beside this answers "which code performed best". This answers the
 * question people actually ask first: *which picture was that?* Somebody who
 * has posted thirty images cannot tell you what `roof-grp-04` looked like, and
 * a row of numbers against a code they do not recognise is not a report.
 *
 * ── THE PICTURE IS THE INDEX ───────────────────────────────────────────────
 * So the list is thumbnails, and clicking one opens the advert at full size
 * with its numbers beside it. The image is the thing they recognise; the code
 * is filing.
 *
 * ── IT SHOWS ZERO AS ZERO ──────────────────────────────────────────────────
 * An advert posted this morning has no visits, and that is a fact rather than
 * a gap. Nothing here hides a number it has, and nothing invents one it does
 * not: no projected earnings, no "trending", no rate off two visits dressed up
 * as a percentage to two decimals.
 */

const when = value => {
  if (!value) return "—"
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return "—"
  return date.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" })
}

/** "3 days ago" reads faster than a date when the date is recent. */
const howLongAgo = value => {
  if (!value) return ""
  const then = new Date(value).getTime()
  if (Number.isNaN(then)) return ""
  const days = Math.floor((Date.now() - then) / 86_400_000)
  if (days <= 0) return "today"
  if (days === 1) return "yesterday"
  if (days < 30) return `${days} days ago`
  const months = Math.floor(days / 30)
  return months === 1 ? "a month ago" : `${months} months ago`
}

const Figure = ({ label, value, note }) => (
  <div className={s.figure}>
    <span className={s.figureLabel}>{label}</span>
    <span className={s.figureValue}>{value}</span>
    {note ? <span className={s.figureNote}>{note}</span> : null}
  </div>
)

const AdGallery = ({ codes = [] }) => {
  const [openCode, setOpenCode] = React.useState("")

  /* Read from the list rather than held separately, so a refresh that brings
     new numbers updates what is open instead of showing a stale copy. */
  const open = codes.find(row => row.code === openCode) || null

  // Escape closes it, the way every other overlay on the web does.
  React.useEffect(() => {
    if (!open) return undefined
    const onKey = event => {
      if (event.key === "Escape") setOpenCode("")
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [open])

  if (codes.length === 0) return null

  return (
    <section className={s.wrap}>
      <div className={s.headRow}>
        <h2 className={s.title}>Your saved adverts</h2>
        <p className={s.lead}>
          {codes.length} saved. Click one to see what it did.
        </p>
      </div>

      <ul className={s.grid}>
        {codes.map(row => (
          <li key={row.code}>
            <button type="button" className={s.tile} onClick={() => setOpenCode(row.code)}>
              <span className={s.shot}>
                {row.imageUrl ? (
                  <img src={row.imageUrl} alt={`Advert ${row.code}`} loading="lazy" />
                ) : (
                  /* Saved before the image was kept, or the upload failed.
                     Said plainly rather than shown as a broken picture. */
                  <span className={s.noShot}>No image saved</span>
                )}
              </span>
              <span className={s.tileBody}>
                <span className={s.tileCode}>{row.code}</span>
                <span className={s.tileWhere}>{row.placedIn || "Group not recorded"}</span>
                <span className={s.tileStats}>
                  <b>{row.visits}</b> visits · <b>{row.sales}</b> sales
                </span>
                <span className={s.tileAge}>{howLongAgo(row.createdAt)}</span>
              </span>
            </button>
          </li>
        ))}
      </ul>

      {open ? (
        <div
          className={s.overlay}
          role="dialog"
          aria-modal="true"
          aria-label={`Advert ${open.code}`}
          onClick={event => {
            // Only the backdrop closes; a click inside the panel is not a miss.
            if (event.target === event.currentTarget) setOpenCode("")
          }}
        >
          <div className={s.panel}>
            <div className={s.panelHead}>
              <div>
                <h3 className={s.panelTitle}>{open.code}</h3>
                <p className={s.panelSub}>
                  {open.placedIn ? `Posted in ${open.placedIn}` : "Group not recorded"}
                </p>
              </div>
              <button type="button" className={s.close} onClick={() => setOpenCode("")}>
                Close
              </button>
            </div>

            <div className={s.panelBody}>
              <div className={s.panelShot}>
                {open.imageUrl ? (
                  <img src={open.imageUrl} alt={`Advert ${open.code}`} />
                ) : (
                  <span className={s.noShot}>No image was saved for this code</span>
                )}
              </div>

              <div className={s.panelStats}>
                <div className={s.figures}>
                  <Figure label="Visits" value={open.visits} note="scanned or clicked" />
                  <Figure label="Sales" value={open.sales} note="went on to buy" />
                  <Figure label="Conversion" value={`${open.rate}%`} note="of visits" />
                </div>

                <dl className={s.facts}>
                  <div>
                    <dt>Made</dt>
                    <dd>
                      {when(open.createdAt)}
                      <span className={s.faint}> · {howLongAgo(open.createdAt)}</span>
                    </dd>
                  </div>
                  <div>
                    <dt>Posted in</dt>
                    <dd>{open.placedIn || "not recorded"}</dd>
                  </div>
                  <div>
                    <dt>Last activity</dt>
                    <dd>{open.lastSeen ? when(open.lastSeen) : "nothing yet"}</dd>
                  </div>
                  {open.template || open.trade ? (
                    <div>
                      <dt>Design</dt>
                      <dd>
                        {open.template || "—"}
                        {open.trade ? ` · ${open.trade}` : ""}
                        {open.size ? ` · ${open.size}` : ""}
                      </dd>
                    </div>
                  ) : null}
                  {open.sources?.length ? (
                    <div>
                      <dt>Came from</dt>
                      <dd>
                        {open.sources.map(source => (
                          <span key={source.name} className={s.source}>
                            {source.name} <b>{source.count}</b>
                          </span>
                        ))}
                      </dd>
                    </div>
                  ) : null}
                  {open.url ? (
                    <div>
                      <dt>Link</dt>
                      <dd className={s.mono}>{open.url}</dd>
                    </div>
                  ) : null}
                </dl>

                <div className={s.panelActions}>
                  {open.imageUrl ? (
                    <a
                      className={s.action}
                      href={open.imageUrl}
                      download={`${open.code}.png`}
                      target="_blank"
                      rel="noreferrer"
                    >
                      Download the image
                    </a>
                  ) : null}
                  {open.url ? (
                    <button
                      type="button"
                      className={`${s.action} ${s.ghost}`}
                      onClick={() => navigator.clipboard?.writeText(open.url)}
                    >
                      Copy the link
                    </button>
                  ) : null}
                </div>
              </div>
            </div>
          </div>
        </div>
      ) : null}
    </section>
  )
}

export default AdGallery
