import * as React from "react"
import "leaflet/dist/leaflet.css"
import { placeOf } from "../../lib/qr-tracking"
import * as s from "./Tracked.module.css"

/**
 * Where the scans happened — FCS-087.
 * ============================================================================
 * Leaflet, which the service-area picker already ships, so this adds no
 * dependency. One circle per place, sized by how many scans were there; a
 * click says which code, how many and when.
 *
 * ── ONLY WHAT IS REALLY KNOWN IS PINNED ────────────────────────────────────
 * A scan that only has a country has no coordinates, and dropping a pin on a
 * country's centre would put dots in the middle of a desert and read as fact.
 * Those scans are counted under the map instead, so nothing is hidden and
 * nothing is invented.
 *
 * ── TILES ──────────────────────────────────────────────────────────────────
 * OpenStreetMap's public tiles, with attribution, for the owner's own
 * dashboard only. They are donated infrastructure, so they are never loaded
 * on a public page — this is behind a login and a paid plan.
 *
 * Leaflet reads `window` at import time, so it loads inside the effect.
 */
const TrackedMap = ({ scans }) => {
  const box = React.useRef(null)
  const map = React.useRef(null)
  const layer = React.useRef(null)
  const lib = React.useRef(null)
  const [ready, setReady] = React.useState(false)

  const pinned = scans.filter(
    x => x.source === "gps" && Number.isFinite(x.lat) && Number.isFinite(x.lng)
  )
  const unpinned = scans.length - pinned.length

  React.useEffect(() => {
    let cancelled = false
    ;(async () => {
      const L = (await import("leaflet")).default
      if (cancelled || !box.current || map.current) return
      lib.current = L
      map.current = L.map(box.current, { worldCopyJump: true, scrollWheelZoom: false }).setView(
        [20, 0],
        2
      )
      L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
        maxZoom: 18,
        attribution: "© OpenStreetMap contributors",
      }).addTo(map.current)
      layer.current = L.layerGroup().addTo(map.current)
      setReady(true)
    })()
    return () => {
      cancelled = true
      if (map.current) {
        map.current.remove()
        map.current = null
      }
    }
  }, [])

  React.useEffect(() => {
    const L = lib.current
    if (!ready || !L || !map.current) return

    layer.current.clearLayers()

    // One circle per place. Coordinates are already rounded to about 100 m,
    // so identical values are genuinely the same spot.
    const places = new Map()
    for (const x of pinned) {
      const key = `${x.lat},${x.lng}`
      if (!places.has(key)) places.set(key, { lat: x.lat, lng: x.lng, rows: [] })
      places.get(key).rows.push(x)
    }

    const points = []
    for (const p of places.values()) {
      const count = p.rows.length
      const marker = L.circleMarker([p.lat, p.lng], {
        radius: Math.min(22, 7 + Math.sqrt(count) * 3),
        color: "#0d3f8f",
        weight: 1.5,
        fillColor: "#1668e8",
        fillOpacity: 0.55,
      })

      // Built as DOM, not an HTML string: a code's name is whatever the
      // owner typed and must never be parsed as markup.
      const pop = document.createElement("div")
      const names = [...new Set(p.rows.map(r => r.qrName))].slice(0, 3).join(", ")
      const title = document.createElement("strong")
      title.textContent = `${count} scan${count === 1 ? "" : "s"}`
      pop.appendChild(title)
      for (const line of [
        names,
        placeOf(p.rows[0]),
        `Latest ${new Date(p.rows[0].scannedAt).toLocaleString()}`,
      ]) {
        const d = document.createElement("div")
        d.textContent = line
        pop.appendChild(d)
      }
      marker.bindPopup(pop)
      marker.addTo(layer.current)
      points.push([p.lat, p.lng])
    }

    if (points.length) {
      map.current.fitBounds(points, { padding: [40, 40], maxZoom: 12 })
    } else {
      map.current.setView([20, 0], 2)
    }
    // Leaflet measures its box once; a tab that was hidden has to be told.
    const t = setTimeout(() => map.current && map.current.invalidateSize(), 60)
    return () => clearTimeout(t)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ready, scans])

  return (
    <div>
      <div
        ref={box}
        className={s.map}
        role="img"
        aria-label="Map of where your codes were scanned"
      />
      <p className={s.mapNote}>
        {pinned.length
          ? `${pinned.length} scan${pinned.length === 1 ? "" : "s"} pinned on the map.`
          : "Nothing to pin yet."}
        {unpinned > 0
          ? ` ${unpinned} more ${unpinned === 1 ? "has" : "have"} no exact position because the person scanning did not share where they were. ${unpinned === 1 ? "It is" : "They are"} in the list.`
          : ""}
      </p>
    </div>
  )
}

export default TrackedMap
