import * as React from "react"
import PlanPicker from "./PlanPicker"
import * as s from "./Upsell.module.css"
import * as l from "./LeadsUpsell.module.css"

/**
 * "The quote form is part of Lead Generation" — FCS-107.
 * ============================================================================
 * One sentence and an outlined button that went to the website builder, on the
 * one screen that is about winning work. Somebody here is looking for the
 * answer to "what would I get, and is it worth money to me", so it shows them:
 * a picture of the thing (a list of quote requests), why a tradesperson wants
 * one (it turns people who looked at the website into people who asked for a
 * price), and what it costs.
 *
 *   1. The ADVERT: the reason, three plain points, and an example inbox.
 *   2. The PLANS, with the quote form marked on the plan that has it. The quote
 *      form is Lead Generation only, so Premium is not marked.
 *
 * ── WHY IT IS A STORY AND NOT A STATISTIC ─────────────────────────────────
 * There is no number here, because there is no number we can stand behind: no
 * "x% more jobs", no "contractors who reply in five minutes win". What can be
 * said truthfully is the mechanism — a quote form lets a visitor ask in a
 * minute instead of phoning around, and every request lands in one list instead
 * of a missed call — and it is said plainly.
 *
 * ── WHAT THE EXAMPLE IS ────────────────────────────────────────────────────
 * Made-up names and requests, labelled as such. The real list (name, phone,
 * email, the job, the message) is what the owner sees once they have the form.
 */

const SAMPLE = [
  {
    name: "Maria Gonzales",
    job: "Kitchen remodel",
    note: "Looking for a quote on a full kitchen update. Could someone call me this week?",
    when: "Just now",
    fresh: true,
  },
  {
    name: "Dave Whitaker",
    job: "Roof repair",
    note: "Slates missing after the wind. I can send photos.",
    when: "12 minutes ago",
    fresh: true,
  },
  {
    name: "Priya Shah",
    job: "Bathroom",
    note: "Replacing the bath with a walk-in shower. Rough budget in mind.",
    when: "Yesterday",
    fresh: false,
  },
]

const LeadsUpsell = ({ currentPlan = "free" }) => (
  <section className={s.wrap} aria-label="Quote requests are part of Lead Generation" data-testid="leads-upsell">
    {/* ── 1. the advert ── */}
    <div className={s.advert}>
      <div className={s.pitch}>
        <span className={s.kicker}>Lead Generation</span>
        <h3 className={s.headline}>Turn people who visit your site into jobs you can quote.</h3>
        <p className={s.copy}>
          A website that only shows your work waits for somebody to pick up the phone. A quote form
          lets them ask in a minute, and every request lands here in one list, instead of getting
          lost in a missed call.
        </p>
        <ul className={s.points}>
          <li>
            <strong>A quote form on your website.</strong> Visitors ask for a price without phoning
            round.
          </li>
          <li>
            <strong>Every request in one list.</strong> Name, phone, email and the job they
            described, newest first.
          </li>
          <li>
            <strong>Know who to call first.</strong> See who asked, for what, and when, so the ones
            worth chasing do not wait.
          </li>
        </ul>
      </div>

      <figure className={s.sample} aria-label="An example of the enquiries list">
        <figcaption className={s.sampleTag}>Example enquiries</figcaption>
        <ul className={l.inbox}>
          {SAMPLE.map(row => (
            <li key={row.name} className={l.lead} data-new={row.fresh ? "true" : undefined}>
              <span className={l.avatar} aria-hidden="true">
                {row.name[0]}
              </span>
              <span className={l.body}>
                <span className={l.top}>
                  <strong className={l.name}>{row.name}</strong>
                  {row.fresh ? <span className={l.chip}>New</span> : null}
                  <span className={l.when}>{row.when}</span>
                </span>
                <span className={l.job}>{row.job}</span>
                <span className={l.note}>{row.note}</span>
              </span>
            </li>
          ))}
        </ul>
        <p className={s.sampleNote}>
          Made-up requests, to show the idea. Yours would be the people who ask through your site.
        </p>
      </figure>
    </div>

    {/* ── 2. the plans ── */}
    <PlanPicker
      currentPlan={currentPlan}
      returnTo="leads"
      unlockedBy={["leads"]}
      badge="Includes the quote form"
      title="Lead Generation adds the tools that bring work in"
      lead="It includes everything in Premium, plus the quote form, premium SEO for your images, design credits and a login for your customers."
    />
  </section>
)

export default LeadsUpsell
