/**
 * The contractor's dashboard — FCS-064.
 * ============================================================================
 * A sidebar and four sections, because a paying customer comes back for
 * different things on different days, and scrolling past three of them to
 * reach the fourth is not a dashboard, it is a page.
 *
 *   Overview    is everything alright, and what changed
 *   My website  the address, whether it is live, and the way to edit it
 *   Enquiries   who wants a quote (Lead Generation only)
 *   Plan        what is being paid, and the recovery code
 *
 * ── THE SECTION IS IN THE ADDRESS ──────────────────────────────────────────
 * `#enquiries` rather than component state alone, so a reload keeps you where
 * you were and a link can point somebody straight at their leads. Somebody
 * refreshing to check for something new and being dropped back on the
 * overview every time is a small thing that becomes infuriating.
 *
 * ── EDITING IS THE BUILDER ─────────────────────────────────────────────────
 * Not a second editor. One way to change a website, rather than two things to
 * keep in step and two things to fix.
 *
 * ── LEADS ARE GATED ON THE SERVER ──────────────────────────────────────────
 * The quote form belongs to one tier. This screen never receives enquiries it
 * is not entitled to show — see functions/my-account, which decides that from
 * the account row rather than trusting the browser to hide them.
 */

const when = value => {
  if (!value) return "—"
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return "—"
  return date.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" })
}

const whenExact = value => {
  if (!value) return "—"
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return "—"
  return `${when(value)}, ${date.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" })}`
}

/* ── WHAT SHOWS WHILE THE ACCOUNT LOADS — FCS-104 ─────────────────────────────
   The Domain row and the credit under the menu both depend on the account, which
   arrives a moment after the page, so they used to appear out of nowhere. The
   shape of each is drawn first (a shimmering placeholder, the same one the domain
   search uses) and the real thing fades in over it. Skeletons are decoration:
   hidden from assistive technology, and the panel says it is busy. */
const Bar = ({ width, thin }) => (
  <span
    className={`${s.skeleton} ${thin ? s.skelThin : s.skelLine}`}
    style={width ? { width } : undefined}
  />
)

const PanelSkeleton = () => (
  <section className={`${s.card} ${s.skelCard}`} aria-busy="true" aria-label="Loading" data-testid="panel-skeleton">
    <Bar width="110px" />
    <div className={s.skelRow}>
      <span className={s.skelLines}>
        <Bar width="44%" />
        <Bar thin width="76%" />
      </span>
      <span className={`${s.skeleton} ${s.skelBtn}`} />
    </div>
  </section>
)

const CreditSkeleton = () => (
  <aside className={`${s.credit} ${s.creditSkel}`} aria-hidden="true" data-testid="credit-skeleton">
    <Bar width="52%" />
    <Bar thin />
    <Bar thin width="80%" />
    <Bar width="34%" />
  </aside>
)

const STATUS_WORDS = {
  live: { word: "Live", tone: "good" },
  building: { word: "Publishing", tone: "wait" },
  draft: { word: "Not published", tone: "wait" },
  failed: { word: "Did not publish", tone: "bad" },
}

/* Line icons at the weight the rest of the site uses, inline rather than from
   a package: four glyphs do not justify a dependency somebody downloads. */
const PATHS = {
  dashboard: "M3 3h6v6H3zM11 3h6v6h-6zM3 11h6v6H3zM11 11h6v6h-6z",
  website:
    "M10 2a8 8 0 1 0 0 16 8 8 0 0 0 0-16zM2 10h16M10 2c2 2.4 3 5 3 8s-1 5.6-3 8c-2-2.4-3-5-3-8s1-5.6 3-8z",
  leads: "M3 5h14v10H3zM3 5l7 5 7-5",
  billing: "M2 6h16v9H2zM2 9h16M5 12.5h3",
  profile: "M10 9.5a3.2 3.2 0 1 0 0-6.4 3.2 3.2 0 0 0 0 6.4zM3.5 17c.4-3 3-4.8 6.5-4.8s6.1 1.8 6.5 4.8",
  settings:
    "M10 12.5a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5zM10 2.5v2M10 15.5v2M3.5 10h-2M18.5 10h-2M5.4 5.4 4 4M16 16l-1.4-1.4M14.6 5.4 16 4M4 16l1.4-1.4",
  invoices: "M5 2h10v16l-2.5-1.7L10 18l-2.5-1.7L5 18zM8 6h4M8 9.5h4",
  qrs: "M3 3h5v5H3zM12 3h5v5h-5zM3 12h5v5H3zM12 12h2v2h-2zM16 16h1M12 16h1v1",
}

const Icon = ({ name }) => (
  <svg
    className={s.navIcon}
    viewBox="0 0 20 20"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.6"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d={PATHS[name]} />
  </svg>
)

const Tile = ({ label, value, note }) => (
  <div className={s.tile}>
    <span className={s.tileLabel}>{label}</span>
    <span className={s.tileValue}>{value}</span>
    {note ? <span className={s.tileNote}>{note}</span> : null}
  </div>
)

/* The seven Nate named — FCS-076. The order is the order somebody meets
   them: what happened, the thing that makes it happen, the two tools, what
   came back, what it costs, and the knobs. */
const SECTIONS = ["dashboard", "website", "invoices", "qrs", "leads", "billing", "profile", "settings"]

/* The old hashes still work. /account/#overview was in receipts, emails and
   whatever anybody bookmarked before this screen grew; silently landing them
   on the wrong tab is worse than the rename was worth. */
const RENAMED = { overview: "dashboard", enquiries: "leads", plan: "billing" }
/* Where an administrator goes from their own account. */
const ADMIN_LINKS = [
  { to: "/admin/users/", label: "All users" },
  { to: "/admin/logs/", label: "Activity log" },
  { to: "/admin/limits/", label: "Plan limits" },
  { to: "/admin/settings/", label: "Settings" },
  { to: "/admin/go-live/", label: "Go-live" },
  { to: "/admin/", label: "Admin home" },
]

const resolveSection = value => {
  const name = String(value || "").replace("#", "")
  const moved = RENAMED[name] || name
  return SECTIONS.includes(moved) ? moved : ""
}

const ContractorAccount = ({ location }) => {
  const { user, ready, signOut, isAdmin } = useAuth()
  const [data, setData] = React.useState(null)
  const [error, setError] = React.useState("")
  const [busy, setBusy] = React.useState(false)

  const fromHash = String(location?.hash || "").replace("#", "")
  const [section, setSection] = React.useState(resolveSection(fromHash) || "dashboard")
  /* Saved or tracked QR codes — FCS-087. */
  const [qrTab, setQrTab] = React.useState("saved")

  /* ── THE DEEP LINK — FCS-078 ──────────────────────────────────────────
     /account/#settings has to land on Settings. Reading the hash once at
     mount was not enough: Gatsby's router settles the location after
     hydration, and for that moment window.location.hash is empty, so the
     read happened and found nothing. Keyed to the location the router hands
     down, it syncs when that settles — and `hashchange` covers somebody
     editing the address bar or following a second link to the same page. */
  React.useEffect(() => {
    const apply = () => {
      const hash = String(
        location?.hash || (typeof window === "undefined" ? "" : window.location.hash)
      )
      const found = resolveSection(hash)
      if (found) setSection(found)
    }
    apply()
    if (typeof window === "undefined") return undefined
    window.addEventListener("hashchange", apply)
    return () => window.removeEventListener("hashchange", apply)
  }, [location?.hash])

  const show = id => {
    setSection(id)
    /* replaceState, not a navigation: the back button should leave the
       dashboard, not walk back through the tabs somebody just clicked. */
    if (typeof window !== "undefined") window.history.replaceState(null, "", `#${id}`)
  }

  React.useEffect(() => {
    if (ready && configured() && !user) navigate("/log-in?next=/account", { replace: true })
  }, [ready, user])

  /* Only the NEWEST request may update the screen. This is fetched again when an
     administrator changes the pretend plan or domain (FCS-095) and every few
     seconds after a payment (FCS-100), so two can be in flight at once, and the
     slower, OLDER one arriving last would overwrite the newer answer with a
     stale one — the screen showing the state from before the last click. */
  const latest = React.useRef(0)

  const load = React.useCallback(async () => {
    const client = supabase()
    if (!client) return
    const mine = ++latest.current
    const current = () => mine === latest.current
    setBusy(true)
    setError("")
    // ?viewAs=<id> turns this tab into an administrator's view of that account (FCS-095).
    adoptViewAsFromUrl()
    try {
      const { data: session } = await client.auth.getSession()
      const token = session?.session?.access_token
      const res = await fetch(apiUrl("my-account"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          apikey: SUPABASE_PUBLISHABLE_KEY,
          Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
        },
        body: "{}",
      })
      const body = await res.json().catch(() => ({}))
      if (!current()) return
      if (!res.ok) {
        // Asked to view somebody and not allowed to: drop out of it rather than loop.
        if (res.status === 403 && getViewAs()) stopViewAs()
        setError(body.message || `We could not load your account (HTTP ${res.status}).`)
        return
      }
      if (body.viewing) rememberViewAsEmail(body.viewing.email)
      // The header greets them by the name on their profile (FCS-113).
      else rememberName(session?.session?.user?.id, body.profileName)
      setData(body)
    } catch {
      if (current()) {
        setError("We could not reach your account just now. Check your connection and try again.")
      }
    } finally {
      if (current()) setBusy(false)
    }
  }, [])

  React.useEffect(() => {
    if (ready && user) load()
  }, [ready, user, load])

  /* Back from Stripe (FCS-100). The plan is written by Stripe's webhook, which
     can land a few seconds after the browser does, so say that the payment is
     in and keep asking until the plan changes, rather than showing the old one
     and looking as though nothing happened. */
  const [justPaid, setJustPaid] = React.useState(false)
  React.useEffect(() => {
    if (typeof window === "undefined") return
    const url = new URL(window.location.href)
    if (url.searchParams.get("checkout") === "success") {
      setJustPaid(true)
      url.searchParams.delete("checkout")
      url.searchParams.delete("session_id")
      window.history.replaceState(null, "", url.pathname + url.search + url.hash)
    }
  }, [])
  React.useEffect(() => {
    if (!justPaid || !ready || !user) return undefined
    let tries = 0
    const timer = setInterval(() => {
      tries += 1
      load()
      if (tries >= 8) clearInterval(timer)
    }, 2500)
    return () => clearInterval(timer)
  }, [justPaid, ready, user, load])

  // Changing the sandbox plan or domain in the test-mode bar re-draws this screen live.
  React.useEffect(
    () => onTestModeChange(() => ready && user && getViewAs() && load()),
    [ready, user, load]
  )

  if (!configured()) {
    return (
      <>
        <Header />
        <main className={s.page}>
          <div className="container">
            <h1 className={s.title}>Your account</h1>
            <p className={s.lead}>{NOT_CONFIGURED}</p>
          </div>
        </main>
      </>
    )
  }

  /* Nothing until the SESSION is known — the same rule the affiliate pages
     follow: a dashboard rendered before it knows whose it is shows somebody
     an empty account that is not theirs.

     Once it knows, the shell is drawn immediately and only the panel waits.
     Holding the whole page back until the data arrives meant no navigation
     and, more to the point, no way to log out — on the screen where somebody
     is most likely to want to. */
  if (!ready || !user) {
    return (
      <>
        <Header />
        <main className={s.page}>
          <div className="container">
            <PageSpinner label="Loading your account…" />
          </div>
        </main>
      </>
    )
  }

  const site = data?.site || null
  const plan = data?.plan || { id: "free", name: "Free", amount: 0 }
  const leads = data?.leads || []
  const status = site ? STATUS_WORDS[site.status] || { word: site.status, tone: "wait" } : null
  const email = data?.email || ""
  const initial = (email[0] || "?").toUpperCase()
  const logOut = () => signOut().then(() => navigate("/"))

  const nav = [
    { id: "dashboard", label: "Dashboard" },
    { id: "website", label: "Website" },
    { id: "invoices", label: "Invoices" },
    { id: "qrs", label: "QR codes" },
    { id: "leads", label: "Leads", count: plan.hasLeadCapture ? leads.length : 0 },
    { id: "billing", label: "Billing" },
    { id: "profile", label: "Profile" },
    { id: "settings", label: "Settings" },
  ]

  const heads = {
    dashboard: { title: "Dashboard", lead: "Everything on your account at a glance." },
    website: { title: "Website", lead: "Your address, and the way to change what is on it." },
    invoices: { title: "Invoices", lead: "Invoices you have saved. Open one to pick up where you left off." },
    qrs: { title: "QR codes", lead: "QR codes you have saved, and codes that count their scans." },
    leads: { title: "Leads", lead: "People who asked for a quote through your website." },
    billing: { title: "Billing", lead: "What you pay for, and what to do if you get locked out." },
    profile: { title: "Profile", lead: "Your name, phone number, address and business details." },
    settings: { title: "Settings", lead: "Your address, your domain, and how people reach you." },
  }

  const websiteCard = (
    <section className={s.card}>
      <div className={s.cardHead}>
        <h2 className={s.cardTitle}>Your website</h2>
        {site ? (
          <span className={s.badge} data-tone={status.tone}>
            {status.word}
          </span>
        ) : null}
      </div>

      {site ? (
        <>
          <div className={s.siteRow}>
            <div>
              <p className={s.siteName}>{site.businessName || site.subdomain}</p>
              <a className={s.siteUrl} href={site.url} target="_blank" rel="noreferrer">
                {site.url.replace(/^https:\/\//, "")}
              </a>
            </div>
            <dl className={s.facts}>
              <div>
                <dt>Published</dt>
                <dd>{when(site.createdAt)}</dd>
              </div>
              <div>
                <dt>Last change</dt>
                <dd>{when(site.updatedAt)}</dd>
              </div>
            </dl>
          </div>

          <div className={s.actions}>
            <Link to="/website-builder" className={s.primary}>
              Edit my website
              <ArrowRight className="btn__arrow" />
            </Link>
            <a className={s.ghost} href={site.url} target="_blank" rel="noreferrer">
              View it
            </a>
            <button type="button" className={s.ghost} onClick={load} disabled={busy}>
              {busy ? "Checking…" : "Refresh"}
            </button>
          </div>
          {/* Where their own address has got to, and what to do if it is waiting (FCS-119). */}
          <HostingNote site={site} onChange={load} />
        </>
      ) : (
        <>
          <p className={s.note}>
            You have not put a website online yet. Building one is free — you only pay when you
            want it hosted on your own address.
          </p>
          <div className={s.actions}>
            <Link to="/website-builder" className={s.primary}>
              Build my website
              <ArrowRight className="btn__arrow" />
            </Link>
            {section === "dashboard" ? (
              <button type="button" className={s.ghost} onClick={() => show("website")}>
                Put a free page online
              </button>
            ) : null}
          </div>
        </>
      )}
    </section>
  )

  const enquiriesCard = !plan.hasLeadCapture ? (
    // No quote form on this plan: say what it would do for them (FCS-107).
    <LeadsUpsell currentPlan={plan.id} />
  ) : (
    <section className={s.card}>
      <div className={s.cardHead}>
        <h2 className={s.cardTitle}>Enquiries</h2>
        <span className={s.badge} data-tone="wait">
          {leads.length}
        </span>
      </div>

      {leads.length === 0 ? (
        <p className={s.note}>
          No enquiries yet. They appear here the moment somebody fills in the form on your
          website — nothing to set up.
        </p>
      ) : (
        <ul className={s.leads}>
          {leads.map(lead => (
            <li key={lead.id} className={s.leadItem}>
              <div className={s.leadHead}>
                <span className={s.leadName}>{lead.name}</span>
                <span className={s.leadWhen}>{whenExact(lead.created_at)}</span>
              </div>
              <div className={s.leadContact}>
                {lead.phone ? <a href={`tel:${lead.phone}`}>{lead.phone}</a> : null}
                {lead.email ? <a href={`mailto:${lead.email}`}>{lead.email}</a> : null}
                {lead.service ? <span className={s.leadService}>{lead.service}</span> : null}
              </div>
              {lead.message ? <p className={s.leadMessage}>{lead.message}</p> : null}
            </li>
          ))}
        </ul>
      )}
    </section>
  )

  const planCard = (
    <BillingPanel
      plan={plan}
      status={data?.account?.subscription || data?.account?.status}
      since={data?.account?.since ? when(data.account.since) : ""}
      recoveryCode={data?.account?.recoveryCode || ""}
    />
  )

  return (
    <>
      <Header />
      <main className={s.page}>
        <div className="container">
          <div className={s.shell}>
            <div className={s.sideCol}>
            <aside className={s.side}>
              <div className={s.who}>
                <span className={s.avatar} aria-hidden="true">
                  {initial}
                </span>
                <span className={s.whoText}>
                  <span className={s.whoName}>{email || "Your account"}</span>
                  <span className={s.whoPlan}>{plan.name}</span>
                </span>
              </div>

              <nav className={s.nav} aria-label="Account sections">
                {nav.map(item => (
                  <button
                    key={item.id}
                    type="button"
                    className={s.navItem}
                    aria-current={section === item.id ? "true" : undefined}
                    onClick={() => show(item.id)}
                  >
                    <Icon name={item.id} />
                    {item.label}
                    {item.count ? <span className={s.navCount}>{item.count}</span> : null}
                  </button>
                ))}
              </nav>

              {/* The way into the admin screens. They existed (FCS-090) but nothing linked
                  to them, so an administrator logging in saw an ordinary account and
                  reasonably concluded there was no admin side. Hidden while looking at
                  somebody else's account, which has to look like theirs. */}
              {isAdmin && !data?.viewing ? (
                <nav className={s.adminNav} aria-label="Admin" data-testid="account-admin-nav">
                  <span className={s.adminNavTitle}>Admin</span>
                  {ADMIN_LINKS.map(link => (
                    <Link key={link.to} to={link.to} className={s.adminNavItem}>
                      {link.label}
                    </Link>
                  ))}
                </nav>
              ) : null}

              <div className={s.sideFoot}>
                <button type="button" className={`${s.ghost} ${s.wide}`} onClick={logOut}>
                  Log out
                </button>
              </div>
            </aside>

            {/* FCS-093. The first-domain credit, under the menu where it is
                seen on every screen. Shown only to somebody with no domain of
                their own: not one connected, not one bought. */}
            {!data && !error ? <CreditSkeleton /> : null}
            {data && data.ownDomain === null && data.offer?.enabled !== false ? (
              <aside className={`${s.credit} ${s.fadeIn}`} aria-label="Domain credit">
                <span className={s.creditAmount}>{money(CREDIT_CENTS)} credit</span>
                <span className={s.creditText}>
                  towards a standard domain for your website. It is yours until you set one up.
                </span>
                <Link to="/account/domain/" className={s.creditLink}>
                  Get a domain
                </Link>
              </aside>
            ) : null}
            </div>

            <div className={s.panel}>
              <div className={s.panelHead}>
                <h1 className={s.title}>{heads[section].title}</h1>
                <p className={s.lead}>{heads[section].lead}</p>
              </div>

              {error ? <p className={s.error}>{error}</p> : null}

              {justPaid ? (
                <p className={s.note} role="status" data-testid="paid-note">
                  {plan.amount > 0
                    ? `Payment received. You are now on ${plan.name}.`
                    : "Payment received. Your plan is updating, which takes a few seconds."}
                </p>
              ) : null}

              {!data && !error ? <PanelSkeleton /> : null}

              {data && section === "dashboard" ? (
                <>
                  <div className={s.tiles}>
                    <Tile
                      label="Website"
                      value={site ? status.word : "None yet"}
                      note={site ? site.subdomain : "build one free"}
                    />
                    <Tile
                      label="Leads"
                      value={plan.hasLeadCapture ? leads.length : "—"}
                      note={plan.hasLeadCapture ? "through your form" : "not on this plan"}
                    />
                    <Tile
                      label="Plan"
                      value={plan.name}
                      note={
                        plan.amount > 0
                          ? `${formatMoney(plan.amount)}/${plan.interval}`
                          : "no charge"
                      }
                    />
                  </div>
                  {websiteCard}
                  {plan.hasLeadCapture && leads.length > 0 ? enquiriesCard : null}
                </>
              ) : null}

              {data && section === "website" ? (
                <>
                  {websiteCard}
                  {/* A free page at freecontractorservices.com/their-name — FCS-118. For somebody with no
                      website yet, or one that already IS a free page; a paid subdomain site has its own address. */}
                  {!site || site.placement === "path" ? <PathPagePanel site={site} onPublished={load} /> : null}
                </>
              ) : null}
              {data && section === "leads" ? enquiriesCard : null}
              {data && section === "billing" ? planCard : null}
              {data && section === "profile" ? <ProfilePanel /> : null}

              {/* ── SAVED WORK — FCS-075 ───────────────────────────────────
                  The Kelley Roads list, one component for both kinds. The
                  tools themselves still live at /invoice-builder/ and
                  /qr-codes/; this is where somebody finds the one they made
                  last Tuesday, which is the part that was missing. */}
              {data && section === "invoices" ? (
                <section className={s.card}>
                  <div className={s.cardHead}>
                    <h2 className={s.cardTitle}>Saved invoices</h2>
                  </div>
                  <SavedDocuments kind="invoice" />
                </section>
              ) : null}

              {data && section === "qrs" ? (
                <section className={s.card}>
                  <div className={s.cardHead}>
                    <h2 className={s.cardTitle}>
                      {qrTab === "tracked" ? "Tracked QR codes" : "Saved QR codes"}
                    </h2>
                  </div>

                  {/* FCS-087. Saved codes are just kept; tracked codes also
                      count their scans, which is the paid part. Two tabs
                      rather than one list, because they answer different
                      questions: "where is my QR" and "what did it do". */}
                  <div className={dp.tabs} role="tablist">
                    <button
                      type="button"
                      role="tab"
                      className={dp.tab}
                      data-on={qrTab === "saved" ? "true" : undefined}
                      aria-selected={qrTab === "saved"}
                      onClick={() => setQrTab("saved")}
                    >
                      Saved
                    </button>
                    <button
                      type="button"
                      role="tab"
                      className={dp.tab}
                      data-on={qrTab === "tracked" ? "true" : undefined}
                      aria-selected={qrTab === "tracked"}
                      onClick={() => setQrTab("tracked")}
                    >
                      Tracked
                    </button>
                  </div>

                  {qrTab === "tracked" ? <TrackedQrs /> : <SavedDocuments kind="qr" />}
                </section>
              ) : null}

              {/* ── DOMAIN — FCS-094 ───────────────────────────────────────
                  One line, not a shop. Searching, buying and connecting a
                  domain moved to its own page (/account/domain/), which has no
                  sidebar and room for the search to be the loud thing on it.
                  Here it is just a row that says where things stand and
                  where to go. */}
              {data && section === "settings" ? (
                <section className={`${s.card} ${s.fadeIn}`}>
                  <div className={s.cardHead}>
                    <h2 className={s.cardTitle}>Domain</h2>
                  </div>
                  <div className={s.settingRow}>
                    <span className={s.settingText}>
                      <span className={s.settingName}>
                        {data.ownDomain ? data.ownDomain.domain : "Not set up yet"}
                      </span>
                      <span className={s.settingNote}>
                        {data.ownDomain
                          ? data.ownDomain.status === "active"
                            ? "Connected to your website."
                            : "Being set up — finish it on the next page."
                          : "Use your own address instead of a freecontractorservices.com one."}
                      </span>
                    </span>
                    <Link to="/account/domain/" className={s.primary}>
                      {data.ownDomain ? "Manage" : "Set up now"}
                    </Link>
                  </div>
                </section>
              ) : null}

              {/* The sidebar's log out is off-screen on a phone, where the nav
                  is a strip with no room for it. */}
              <div className={`${s.actions} ${s.phoneOnly}`}>
                <button type="button" className={`${s.ghost} ${s.wide}`} onClick={logOut}>
                  Log out
                </button>
              </div>
            </div>
          </div>
        </div>
      </main>
    </>
  )
}

export const Head = () => (
  <Seo title="Your account" description="Your website, your enquiries and your plan." noindex />
)

/* ── WHICH ACCOUNT SCREEN — FCS-110 ───────────────────────────────────────
   An affiliate is not a contractor: they get Dashboard, Affiliate, Billing and
   Settings, not Website, Invoices, QR codes and Leads. Until we know which of the
   two this is, show the frame with placeholders rather than the contractor
   screen for a moment — the same flash FCS-104 took out of the Domain row.
   An administrator viewing a customer sees that customer's screen, whoever they
   are themselves. */
const AccountPage = props => {
  const { user, isAffiliate, rolesReady } = useAuth()
  const viewing = useViewAs()

  if (user && !rolesReady) {
    return (
      <>
        <Header />
        <main className={s.page}>
          <div className="container">
            <div className={s.shell}>
              <div className={s.sideCol}>
                <aside className={`${s.side} ${s.skelCard}`} aria-hidden="true">
                  <Bar width="60%" />
                  <Bar thin />
                  <Bar thin width="80%" />
                  <Bar thin />
                </aside>
              </div>
              <div className={s.panel}>
                <PanelSkeleton />
              </div>
            </div>
          </div>
        </main>
      </>
    )
  }

  return isAffiliate && !viewing ? <AffiliateAccount location={props.location} /> : <ContractorAccount {...props} />
}

export default AccountPage
