import { apiUrl } from "../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../config/supabase-public"
import { supabase } from "./supabase"

/**
 * Trackable QR codes, from the browser — FCS-087.
 * ============================================================================
 * One call() for the signed-in dashboard, and one scan() for the public page
 * a QR code opens. They are kept apart on purpose: the scan page belongs to a
 * stranger with no account and must never reach for a session.
 */

export async function track(body) {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token

  const res = await fetch(apiUrl("qr-tracking"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
    },
    body: JSON.stringify(body),
  })
  return { ok: res.ok, status: res.status, body: await res.json().catch(() => ({})) }
}

/**
 * Where somebody was, if they will say.
 *
 * Asks the browser once, gives up quickly, and never blocks: the person
 * holding the phone wants the page they scanned, not a permission dialog.
 * Resolves to null for every way of not having an answer — denied, timed out,
 * unsupported, an insecure origin — because to the caller they are the same.
 */
export function whereAmI({ timeout = 4000 } = {}) {
  return new Promise(resolve => {
    if (typeof navigator === "undefined" || !navigator.geolocation) return resolve(null)

    let done = false
    const finish = value => {
      if (done) return
      done = true
      resolve(value)
    }
    // The browser's own timeout does not cover the permission prompt sitting
    // unanswered, so this one does.
    const timer = setTimeout(() => finish(null), timeout + 500)

    const ask = () =>
      navigator.geolocation.getCurrentPosition(
        pos => {
          clearTimeout(timer)
          finish({ lat: pos.coords.latitude, lng: pos.coords.longitude })
        },
        () => {
          clearTimeout(timer)
          finish(null)
        },
        // Rough is enough and quicker: a city block, not a front door.
        { enableHighAccuracy: false, timeout, maximumAge: 10 * 60 * 1000 }
      )

    // Somebody who has already said no should not wait for a second no.
    if (navigator.permissions?.query) {
      navigator.permissions
        .query({ name: "geolocation" })
        .then(p => {
          if (p.state === "denied") {
            clearTimeout(timer)
            finish(null)
          } else {
            ask()
          }
        })
        .catch(ask)
    } else {
      ask()
    }
  })
}

/** Records a scan and returns where to send the visitor, or null. */
export async function scan(code, where) {
  try {
    const res = await fetch(apiUrl("qr-scan"), {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        apikey: SUPABASE_PUBLISHABLE_KEY,
        Authorization: `Bearer ${SUPABASE_PUBLISHABLE_KEY}`,
      },
      body: JSON.stringify({ code, lat: where?.lat, lng: where?.lng }),
    })
    const body = await res.json().catch(() => ({}))
    return body.destination || null
  } catch {
    return null
  }
}

/** How a scan's position reads in a list. */
export function placeOf(scan) {
  const named = [scan.city, scan.region, scan.country].filter(Boolean).join(", ")
  if (scan.source === "gps" && scan.lat !== null && scan.lat !== undefined) {
    const at = `${Number(scan.lat).toFixed(3)}, ${Number(scan.lng).toFixed(3)}`
    return named ? `${named} (${at})` : at
  }
  if (scan.source === "country" && scan.country) return scan.country
  return "Location not shared"
}

export const PRECISION = {
  gps: { label: "Exact", note: "Their device shared its position" },
  country: { label: "Country", note: "Only the country is known" },
  none: { label: "Unknown", note: "Nothing is known about where" },
}
