import * as React from "react"
import { PRECISION, placeOf, track } from "../../lib/qr-tracking"
import TrackedMap from "./TrackedMap"
import * as s from "./Tracked.module.css"

/**
 * The map, the list behind it, and the one-glance summary — FCS-087.
 * ============================================================================
 * "When I used this code in this place, it was linked to these results": one
 * filter (everything, a campaign, or a single code) drives all three, so the
 * map, the list and the summary can never be describing different things.
 *
 * ── THE SUMMARY STATES ITS OWN LIMITS ──────────────────────────────────────
 * It says how many scans carry an exact position. A map with six pins out of
 * sixty is only honest if the screen says it is six out of sixty; otherwise a
 * quiet map reads as a quiet code.
 */

const PAGE = 25

const Stat = ({ label, value, note }) => (
  <div className={s.stat}>
    <span className={s.statLabel}>{label}</span>
    <span className={s.statValue}>{value}</span>
    {note ? <span className={s.statNote}>{note}</span> : null}
  </div>
)

const TrackedInsights = ({ data }) => {
  const [filter, setFilter] = React.useState("all")
  const [scans, setScans] = React.useState(null)
  const [error, setError] = React.useState("")
  const [shown, setShown] = React.useState(PAGE)

  React.useEffect(() => {
    let alive = true
    setScans(null)
    setShown(PAGE)
    const body = { action: "scans" }
    if (filter.startsWith("c:")) body.campaignId = filter.slice(2)
    if (filter.startsWith("q:")) body.qrId = filter.slice(2)
    track(body).then(res => {
      if (!alive) return
      if (!res.ok) return setError(res.body.message || "Could not load the scans.")
      setError("")
      setScans(res.body.scans || [])
    })
    return () => {
      alive = false
    }
  }, [filter])

  const summary = React.useMemo(() => {
    if (!scans) return null
    const now = Date.now()
    const within = days => scans.filter(x => now - new Date(x.scannedAt).getTime() <= days * 864e5).length
    const exact = scans.filter(x => x.source === "gps").length

    const tally = (key, rows) => {
      const m = new Map()
      for (const r of rows) {
        const k = key(r)
        if (k) m.set(k, (m.get(k) || 0) + 1)
      }
      return [...m.entries()].sort((a, b) => b[1] - a[1])
    }
    return {
      total: scans.length,
      week: within(7),
      month: within(30),
      exact,
      countries: tally(x => x.country, scans).slice(0, 3),
      codes: tally(x => x.qrName, scans).slice(0, 1),
    }
  }, [scans])

  return (
    <div>
      <label className={s.filter}>
        <span>Show</span>
        <select className={s.input} value={filter} onChange={e => setFilter(e.target.value)}>
          <option value="all">Every code</option>
          {data.campaigns.length ? (
            <optgroup label="A campaign">
              {data.campaigns.map(c => (
                <option key={c.id} value={`c:${c.id}`}>
                  {c.name}
                </option>
              ))}
            </optgroup>
          ) : null}
          {data.codes.length ? (
            <optgroup label="One code">
              {data.codes.map(c => (
                <option key={c.id} value={`q:${c.id}`}>
                  {c.name}
                </option>
              ))}
            </optgroup>
          ) : null}
        </select>
      </label>

      {error ? <p className={s.error}>{error}</p> : null}
      {!scans && !error ? <p className={s.note}>Loading scans…</p> : null}

      {scans && summary ? (
        <>
          <div className={s.stats}>
            <Stat label="Scans" value={summary.total} />
            <Stat label="Last 7 days" value={summary.week} note={`${summary.month} in 30 days`} />
            <Stat
              label="Exact position"
              value={summary.total ? `${summary.exact} of ${summary.total}` : "—"}
              note={summary.total ? "the rest did not share where they were" : ""}
            />
            <Stat
              label="Top places"
              value={summary.countries.length ? summary.countries.map(c => c[0]).join(", ") : "—"}
              note={summary.countries.map(c => `${c[0]} ${c[1]}`).join(" · ")}
            />
          </div>
          {summary.codes[0] && filter === "all" ? (
            <p className={s.hint}>
              Busiest code: <strong>{summary.codes[0][0]}</strong> with {summary.codes[0][1]} scan
              {summary.codes[0][1] === 1 ? "" : "s"}.
            </p>
          ) : null}

          <TrackedMap scans={scans} />

          <h3 className={s.h3}>Every scan</h3>
          {scans.length ? (
            <>
              <div className={s.tableWrap}>
                <table className={s.table}>
                  <thead>
                    <tr>
                      <th scope="col">When</th>
                      <th scope="col">Code</th>
                      <th scope="col">Where</th>
                      <th scope="col">How sure</th>
                    </tr>
                  </thead>
                  <tbody>
                    {scans.slice(0, shown).map(x => (
                      <tr key={x.id}>
                        <td>{new Date(x.scannedAt).toLocaleString()}</td>
                        <td>{x.qrName}</td>
                        <td>{placeOf(x)}</td>
                        <td>
                          <span className={s.pill} title={PRECISION[x.source]?.note}>
                            {PRECISION[x.source]?.label || x.source}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {shown < scans.length ? (
                <button type="button" className={s.small} onClick={() => setShown(n => n + PAGE)}>
                  Show more ({scans.length - shown} left)
                </button>
              ) : null}
            </>
          ) : (
            <p className={s.note}>No scans yet. They appear here the moment a code is scanned.</p>
          )}
        </>
      ) : null}
    </div>
  )
}

export default TrackedInsights
