import * as React from "react"
import { Link } from "gatsby"
import PlanPicker from "./PlanPicker"
import * as s from "./Upsell.module.css"

/**
 * "Saved invoices are part of a paid plan" — FCS-101.
 * ============================================================================
 * Shown where the saved invoices would be, when the plan does not keep them.
 * The same shape as the tracked-QR upsell (FCS-100), because it is the same
 * moment: somebody meets a wall, and wants to know what is behind it, what
 * else comes with it, and how to get through.
 *
 *   1. The ADVERT: what keeping invoices gets you, with an example list.
 *   2. The PLANS, shared with every other wall (PlanPicker).
 *
 * ── IT DOES NOT SAY THE TOOL IS CLOSED ─────────────────────────────────────
 * The invoice builder is free and stays free: build one, download the PDF.
 * What a paid plan adds is KEEPING them. Saying "invoices are paid" would be
 * wrong, and would send somebody away from a tool that works for them, so the
 * first thing under the advert is the way back into the builder.
 *
 * ── THE EXAMPLE IS LABELLED ────────────────────────────────────────────────
 * The sample names and dates are made up, and say so. Everything else here is
 * read from the plan data, so it cannot promise what the checkout does not sell.
 */

const SAMPLE = [
  { name: "Kitchen remodel, Smith", when: "Saved Tuesday" },
  { name: "Roof repair, 14 Oak Street", when: "Saved Monday" },
  { name: "Deck, final payment", when: "Saved last week" },
]

const InvoicesUpsell = ({ currentPlan = "free" }) => (
  <section className={s.wrap} aria-label="Saved invoices are part of a paid plan" data-testid="invoices-upsell">
    {/* ── 1. the advert ── */}
    <div className={s.advert}>
      <div className={s.pitch}>
        <span className={s.kicker}>Saved invoices</span>
        <h3 className={s.headline}>Keep every invoice, and find it again.</h3>
        <p className={s.copy}>
          On the free plan an invoice lives only in the browser you built it in. On a paid plan,
          every invoice you save is kept in your account, so last Tuesday’s kitchen job is one
          click away.
        </p>
        <ul className={s.points}>
          <li>
            <strong>Kept in your account.</strong> Open it from any device you log in on, not just
            the one you built it on.
          </li>
          <li>
            <strong>Found by name.</strong> “Kitchen job, Tuesday”, in your own words, not a
            number.
          </li>
          <li>
            <strong>Open it and carry on.</strong> Pick an invoice up where you left it, change it
            and save it again.
          </li>
        </ul>
        <p className={s.heroNote}>
          You can still build invoices and download them as PDFs for free.{" "}
          <Link className={s.heroLink} to="/invoice-builder/">
            Open the invoice builder
          </Link>
        </p>
      </div>

      <figure className={s.sample} aria-label="An example of saved invoices">
        <figcaption className={s.sampleTag}>Example saved invoices</figcaption>
        <ul className={s.log}>
          {SAMPLE.map(row => (
            <li key={row.name} className={s.logRow}>
              <span className={s.logAdvert}>{row.name}</span>
              <span className={s.logMeta}>{row.when}</span>
              <span className={s.logCount}>Open</span>
            </li>
          ))}
        </ul>
        <p className={s.sampleNote}>
          Made-up names, to show the idea. Yours would be the invoices you save.
        </p>
      </figure>
    </div>

    {/* ── 2. the plans ── */}
    <PlanPicker
      currentPlan={currentPlan}
      returnTo="invoices"
      badge="Includes saved invoices"
      title="Saved invoices come with a paid plan"
      lead="A paid plan keeps your invoices in your account and puts a website on your own address beside them. Lead Generation adds the tools that bring work in."
    />
  </section>
)

export default InvoicesUpsell
