import * as React from "react"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../context/auth"
import { rememberName } from "../../lib/display-name"
import * as d from "./Dashboard.module.css"
import * as s from "./ProfilePanel.module.css"

/**
 * Who you are — FCS-113.
 * ============================================================================
 * Name, phone, business and address, in one form, saved in one go. The email
 * is shown but is not a field: it is the login, and changing it is a support
 * job (it confirms the new address and moves the account), not a text box.
 *
 * Everything is optional. Nothing here gates anything else in the product, so
 * a half-filled form saves as half-filled rather than being refused.
 */

const FIELDS = [
  { key: "fullName", label: "Full name", auto: "name", wide: true },
  { key: "phone", label: "Phone number", auto: "tel", type: "tel" },
  { key: "businessName", label: "Business name", auto: "organization" },
  { key: "addressLine1", label: "Address", auto: "address-line1", wide: true },
  { key: "addressLine2", label: "Apartment, suite, unit (optional)", auto: "address-line2", wide: true },
  { key: "city", label: "City", auto: "address-level2" },
  { key: "region", label: "State / region", auto: "address-level1" },
  { key: "postcode", label: "ZIP / postcode", auto: "postal-code" },
  { key: "country", label: "Country", auto: "country-name" },
]

const BLANK = Object.fromEntries(FIELDS.map(f => [f.key, ""]))

const call = async body => {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token
  const res = await fetch(apiUrl("my-profile"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
    },
    body: JSON.stringify(body),
  })
  return { ok: res.ok, body: await res.json().catch(() => ({})) }
}

const ProfilePanel = () => {
  const { user } = useAuth()
  const [saved, setSaved] = React.useState(null) // what the server has
  const [form, setForm] = React.useState(BLANK)
  const [email, setEmail] = React.useState("")
  const [hidden, setHidden] = React.useState(false)
  const [loading, setLoading] = React.useState(true)
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState("")
  const [note, setNote] = React.useState("")

  React.useEffect(() => {
    let alive = true
    call({ action: "get" }).then(res => {
      if (!alive) return
      setLoading(false)
      if (!res.ok) {
        setError(res.body.message || "We could not load your profile.")
        return
      }
      setEmail(res.body.email || "")
      if (res.body.hidden) {
        setHidden(true)
        return
      }
      setSaved(res.body.profile)
      setForm({ ...BLANK, ...res.body.profile })
    })
    return () => {
      alive = false
    }
  }, [])

  const dirty = saved ? FIELDS.some(f => (form[f.key] || "") !== (saved[f.key] || "")) : false

  const change = (key, value) => {
    setForm(current => ({ ...current, [key]: value }))
    setNote("")
  }

  const submit = async event => {
    event.preventDefault()
    setBusy(true)
    setError("")
    setNote("")
    const res = await call({ action: "save", ...form })
    setBusy(false)
    if (!res.ok) {
      setError(res.body.message || "That could not be saved.")
      return
    }
    setSaved(res.body.profile)
    setForm({ ...BLANK, ...res.body.profile })
    rememberName(user?.id, res.body.profile.fullName)
    setNote("Saved.")
  }

  if (loading) {
    return (
      <section className={`${d.card} ${d.skelCard}`} aria-busy="true" aria-label="Loading" data-testid="panel-skeleton">
        <span className={`${d.skeleton} ${d.skelLine}`} style={{ width: 120 }} />
        <span className={`${d.skeleton} ${d.skelThin}`} style={{ width: "70%" }} />
        <span className={`${d.skeleton} ${d.skelThin}`} style={{ width: "55%" }} />
      </section>
    )
  }

  if (hidden) {
    return (
      <section className={d.card}>
        <div className={d.cardHead}>
          <h2 className={d.cardTitle}>Profile</h2>
        </div>
        <p className={d.note}>
          A customer&apos;s name, phone number and address are not shown while you are viewing their account.
        </p>
      </section>
    )
  }

  return (
    <form className={d.card} onSubmit={submit} data-testid="profile-form">
      <div className={d.cardHead}>
        <h2 className={d.cardTitle}>Your details</h2>
      </div>

      <div className={s.grid}>
        <div className={`${s.field} ${s.wide}`}>
          <label htmlFor="pf-email">Email</label>
          <input id="pf-email" value={email} readOnly disabled />
          <span className={s.hint}>This is what you log in with. To change it, get in touch.</span>
        </div>

        {FIELDS.map(f => (
          <div key={f.key} className={`${s.field} ${f.wide ? s.wide : ""}`}>
            <label htmlFor={`pf-${f.key}`}>{f.label}</label>
            <input
              id={`pf-${f.key}`}
              type={f.type || "text"}
              autoComplete={f.auto}
              value={form[f.key]}
              onChange={e => change(f.key, e.target.value)}
              maxLength={f.key === "fullName" || f.key === "businessName" || f.key.startsWith("address") ? 120 : 80}
            />
          </div>
        ))}
      </div>

      {error ? <p className={d.error}>{error}</p> : null}

      <div className={s.bar}>
        <button type="submit" className={d.primary} disabled={busy || !dirty}>
          {busy ? "Saving…" : "Save profile"}
        </button>
        <span className={s.status} role="status">
          {note}
        </span>
      </div>
    </form>
  )
}

export default ProfilePanel
