import * as React from "react"
import { track } from "../../lib/qr-tracking"
import LineChart from "./LineChart"
import * as s from "./Tracked.module.css"

/**
 * Campaigns, and the comparison — FCS-087.
 * ============================================================================
 * A campaign is a name, a description, and the codes filed under it. Its
 * whole reason to exist is the graph: "the van codes against the flyer codes
 * over the last month", one line each.
 *
 * Deleting a campaign never deletes codes. They are un-filed, scans intact —
 * a grouping is a label, and removing a label must not destroy the data it
 * was describing.
 */

const RANGES = [
  { days: 7, label: "7 days" },
  { days: 30, label: "30 days" },
  { days: 90, label: "90 days" },
]

const TrackedCampaigns = ({ data, reload, setError }) => {
  const [name, setName] = React.useState("")
  const [description, setDescription] = React.useState("")
  const [editing, setEditing] = React.useState("")
  const [draft, setDraft] = React.useState({ name: "", description: "" })
  const [confirming, setConfirming] = React.useState("")
  const [busy, setBusy] = React.useState(false)
  const [days, setDays] = React.useState(30)
  const [series, setSeries] = React.useState(null)

  React.useEffect(() => {
    let alive = true
    setSeries(null)
    track({ action: "series", days }).then(res => {
      if (!alive) return
      if (!res.ok) return setError(res.body.message || "Could not load the comparison.")
      setSeries(res.body)
    })
    return () => {
      alive = false
    }
  }, [days, data.totalScans, data.campaigns.length, setError])

  const call = async body => {
    setBusy(true)
    setError("")
    const res = await track(body)
    setBusy(false)
    if (!res.ok) {
      setError(res.body.message || "That did not work.")
      return false
    }
    await reload()
    return true
  }

  const create = async event => {
    event.preventDefault()
    if (await call({ action: "campaign-save", name, description })) {
      setName("")
      setDescription("")
    }
  }

  const saveEdit = async event => {
    event.preventDefault()
    if (await call({ action: "campaign-save", id: editing, ...draft })) setEditing("")
  }

  const onlyUnfiled =
    series && series.series.every(x => x.id === "none" || x.total === 0) && data.campaigns.length === 0

  return (
    <div>
      <form className={s.create} onSubmit={create}>
        <h3 className={s.h3}>New campaign</h3>
        <div className={s.fields}>
          <label className={s.field}>
            <span>Name</span>
            <input
              className={s.input}
              value={name}
              onChange={e => setName(e.target.value)}
              placeholder="Spring vans"
              maxLength={120}
            />
          </label>
          <label className={s.field}>
            <span>Description (optional)</span>
            <input
              className={s.input}
              value={description}
              onChange={e => setDescription(e.target.value)}
              placeholder="What it is, where the codes went"
              maxLength={600}
            />
          </label>
        </div>
        <button type="submit" className={s.primaryBtn} disabled={busy || !name.trim()}>
          Create campaign
        </button>
        <p className={s.hint}>
          File a code under a campaign from its Edit button on the Codes tab, or choose one when
          you make it.
        </p>
      </form>

      <div className={s.compare}>
        <div className={s.compareHead}>
          <h3 className={s.h3}>Compare campaigns</h3>
          <span className={s.row}>
            {RANGES.map(r => (
              <button
                key={r.days}
                type="button"
                className={s.small}
                data-on={days === r.days ? "true" : undefined}
                onClick={() => setDays(r.days)}
              >
                {r.label}
              </button>
            ))}
          </span>
        </div>

        {!series ? <p className={s.note}>Loading the comparison…</p> : null}
        {series ? <LineChart dates={series.dates} series={series.series} /> : null}
        {onlyUnfiled ? (
          <p className={s.hint}>
            Make a campaign and file some codes under it to see them as separate lines.
          </p>
        ) : null}
      </div>

      {data.campaigns.length ? (
        <ul className={s.codes}>
          {data.campaigns.map(c => (
            <li key={c.id} className={s.campaign}>
              {editing === c.id ? (
                <form className={s.editForm} onSubmit={saveEdit}>
                  <input
                    className={s.input}
                    value={draft.name}
                    onChange={e => setDraft(d => ({ ...d, name: e.target.value }))}
                    aria-label="Campaign name"
                    maxLength={120}
                  />
                  <input
                    className={s.input}
                    value={draft.description}
                    onChange={e => setDraft(d => ({ ...d, description: e.target.value }))}
                    aria-label="Description"
                    maxLength={600}
                  />
                  <span className={s.row}>
                    <button type="submit" className={s.small} disabled={busy}>
                      Save
                    </button>
                    <button type="button" className={s.small} onClick={() => setEditing("")}>
                      Cancel
                    </button>
                  </span>
                </form>
              ) : (
                <>
                  <span className={s.codeBody}>
                    <span className={s.codeName}>{c.name}</span>
                    {c.description ? <span className={s.codeDest}>{c.description}</span> : null}
                    <span className={s.codeStats}>
                      <strong>{c.codes}</strong> code{c.codes === 1 ? "" : "s"} ·{" "}
                      <strong>{c.scans}</strong> scan{c.scans === 1 ? "" : "s"}
                    </span>
                  </span>
                  <span className={s.row}>
                    <button
                      type="button"
                      className={s.small}
                      onClick={() => {
                        setDraft({ name: c.name, description: c.description })
                        setEditing(c.id)
                      }}
                    >
                      Edit
                    </button>
                    {confirming === c.id ? (
                      <>
                        <button
                          type="button"
                          className={`${s.small} ${s.danger}`}
                          disabled={busy}
                          onClick={async () => {
                            await call({ action: "campaign-delete", id: c.id })
                            setConfirming("")
                          }}
                        >
                          Delete (keeps the codes)
                        </button>
                        <button type="button" className={s.small} onClick={() => setConfirming("")}>
                          Keep
                        </button>
                      </>
                    ) : (
                      <button type="button" className={s.small} onClick={() => setConfirming(c.id)}>
                        Delete
                      </button>
                    )}
                  </span>
                </>
              )}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  )
}

export default TrackedCampaigns
