import * as React from "react"
import { supabase } from "./supabase"
import { apiUrl } from "../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../config/supabase-public"

/**
 * What an affiliate's adverts did — MTC-FCS-041, moved here for FCS-110.
 * ============================================================================
 * The report used to live inside the /affiliate page. An affiliate now works
 * from their ordinary account screen (Dashboard, Affiliate, Billing, Settings),
 * and two of those four screens read the same numbers, so the fetch is one hook
 * rather than two copies that drift.
 *
 * An Edge Function, not /api — FCS-067: the Gatsby route does not exist on a
 * static host. An empty report is a normal answer (zeroes and a line saying what
 * to do next), never an error.
 */
export function useAffiliateReport(enabled) {
  const [report, setReport] = React.useState(null)
  const [error, setError] = React.useState("")
  const [busy, setBusy] = React.useState(false)

  const load = React.useCallback(async () => {
    const client = supabase()
    if (!client) return
    setBusy(true)
    setError("")
    try {
      const { data } = await client.auth.getSession()
      const token = data?.session?.access_token
      const res = await fetch(apiUrl("affiliate-report"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          apikey: SUPABASE_PUBLISHABLE_KEY,
          Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
        },
        body: "{}",
      })
      const body = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(body.message || `Could not load the report (HTTP ${res.status}).`)
        return
      }
      setReport(body)
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy(false)
    }
  }, [])

  React.useEffect(() => {
    if (enabled) load()
  }, [enabled, load])

  return { report, error, busy, load }
}
