import * as React from "react"
import { PATTERNS, SWATCHES } from "../../lib/qr"
import { track } from "../../lib/qr-tracking"
import TrackedQrImage from "./TrackedQrImage"
import TrackedInsights from "./TrackedInsights"
import TrackedCampaigns from "./TrackedCampaigns"
import TrackingUpsell from "./TrackingUpsell"
import * as s from "./Tracked.module.css"

/**
 * Trackable QR codes — FCS-087.
 * ============================================================================
 * A paid feature: make a code, print it, and every scan is recorded — when,
 * and where if the scanner allows it — so "when I put this one on that van,
 * this is what came back" has an answer.
 *
 *   Codes             make them, download them, pause or retarget them
 *   Map and scans     where they were scanned, and the list behind the map
 *   Campaigns         group codes, and set the groups against each other
 *
 * ── THE CODE IS PRINTED ONCE ───────────────────────────────────────────────
 * What the QR encodes is our own short address, never the destination. That
 * is what makes it trackable at all, and it is also why the destination can be
 * changed later without reprinting anything.
 *
 * ── THE PLAN IS EXPLAINED, NOT JUST ENFORCED ───────────────────────────────
 * The server owns the cap (a cap the browser can skip is not a cap). This
 * screen only says what it is, so a closed plan reads as "this is part of a
 * paid plan" with a way to get there, rather than as a form that fails.
 */

const TABS = [
  { id: "codes", label: "Codes" },
  { id: "insights", label: "Map & scans" },
  { id: "campaigns", label: "Campaigns" },
]

const Banner = ({ allowance }) => {
  const { limit, used, creditsPerUse } = allowance
  // A closed plan is an invitation: what tracking tells you, the plans, and the way there (FCS-100).
  if (limit === 0) return <TrackingUpsell currentPlan={allowance.tier} />
  return (
    <p className={s.allowance}>
      <strong>{used}</strong> of{" "}
      <strong>{limit === null || limit === undefined ? "unlimited" : limit}</strong> trackable
      codes used.
      {creditsPerUse !== null && creditsPerUse !== undefined
        ? ` Priced at ${creditsPerUse} credit${creditsPerUse === 1 ? "" : "s"} each — credits are not charged yet.`
        : ""}
    </p>
  )
}

const CodeRow = ({ code, campaigns, reload, setError }) => {
  const [editing, setEditing] = React.useState(false)
  const [confirming, setConfirming] = React.useState(false)
  const [busy, setBusy] = React.useState(false)
  const [copied, setCopied] = React.useState(false)
  const [draft, setDraft] = React.useState({})
  const image = React.useRef(null)

  const campaign = campaigns.find(c => c.id === code.campaignId)

  const act = async body => {
    setBusy(true)
    setError("")
    const res = await track({ id: code.id, ...body })
    setBusy(false)
    if (!res.ok) {
      setError(res.body.message || "That did not work.")
      return false
    }
    await reload()
    return true
  }

  const save = async event => {
    event.preventDefault()
    if (await act({ action: "update", name: draft.name, destination: draft.destination, campaignId: draft.campaignId })) {
      setEditing(false)
    }
  }

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(code.url)
      setCopied(true)
      setTimeout(() => setCopied(false), 1600)
    } catch {
      setError("Could not copy — select the address and copy it by hand.")
    }
  }

  return (
    <li className={s.code} data-paused={code.active ? undefined : "true"} data-busy={busy ? "true" : undefined}>
      <TrackedQrImage url={code.url} style={code.style} size={96} instanceRef={image} />

      <div className={s.codeBody}>
        {editing ? (
          <form className={s.editForm} onSubmit={save}>
            <input
              className={s.input}
              value={draft.name}
              onChange={e => setDraft(d => ({ ...d, name: e.target.value }))}
              aria-label="Name"
              maxLength={120}
            />
            <input
              className={s.input}
              value={draft.destination}
              onChange={e => setDraft(d => ({ ...d, destination: e.target.value }))}
              aria-label="Where it goes"
            />
            <select
              className={s.input}
              value={draft.campaignId}
              onChange={e => setDraft(d => ({ ...d, campaignId: e.target.value }))}
              aria-label="Campaign"
            >
              <option value="">No campaign</option>
              {campaigns.map(c => (
                <option key={c.id} value={c.id}>
                  {c.name}
                </option>
              ))}
            </select>
            <span className={s.row}>
              <button type="submit" className={s.small} disabled={busy}>
                Save
              </button>
              <button type="button" className={s.small} onClick={() => setEditing(false)}>
                Cancel
              </button>
            </span>
          </form>
        ) : (
          <>
            <span className={s.codeName}>
              {code.name}
              {!code.active ? <span className={s.pill}>Paused</span> : null}
              {campaign ? <span className={s.pillBlue}>{campaign.name}</span> : null}
            </span>
            <span className={s.codeDest}>Goes to {code.destination}</span>
            <span className={s.codeStats}>
              <strong>{code.scans}</strong> scan{code.scans === 1 ? "" : "s"}
              {code.lastScan ? ` · last ${new Date(code.lastScan).toLocaleDateString()}` : " · none yet"}
            </span>

            <span className={s.row}>
              <button
                type="button"
                className={s.small}
                onClick={() =>
                  image.current &&
                  image.current.download({ name: `qr-${code.code}`, extension: "png" })
                }
              >
                Download
              </button>
              <button type="button" className={s.small} onClick={copy}>
                {copied ? "Copied" : "Copy link"}
              </button>
              <button
                type="button"
                className={s.small}
                onClick={() => {
                  setDraft({
                    name: code.name,
                    destination: code.destination,
                    campaignId: code.campaignId || "",
                  })
                  setEditing(true)
                }}
              >
                Edit
              </button>
              <button
                type="button"
                className={s.small}
                disabled={busy}
                onClick={() => act({ action: "update", active: !code.active })}
              >
                {code.active ? "Pause" : "Resume"}
              </button>
              {confirming ? (
                <>
                  <button
                    type="button"
                    className={`${s.small} ${s.danger}`}
                    disabled={busy}
                    onClick={() => act({ action: "delete" })}
                  >
                    Delete with its scans
                  </button>
                  <button type="button" className={s.small} onClick={() => setConfirming(false)}>
                    Keep
                  </button>
                </>
              ) : (
                <button type="button" className={s.small} onClick={() => setConfirming(true)}>
                  Delete
                </button>
              )}
            </span>
          </>
        )}
      </div>
    </li>
  )
}

const CodesPanel = ({ data, reload, setError }) => {
  const [name, setName] = React.useState("")
  const [destination, setDestination] = React.useState("")
  const [campaignId, setCampaignId] = React.useState("")
  const [colour, setColour] = React.useState(SWATCHES[0])
  const [pattern, setPattern] = React.useState("rounded")
  const [busy, setBusy] = React.useState(false)

  const { allowance, codes, campaigns } = data
  const full =
    allowance.limit !== null && allowance.limit !== undefined && allowance.used >= allowance.limit

  const create = async event => {
    event.preventDefault()
    setBusy(true)
    setError("")
    const res = await track({
      action: "create",
      name,
      destination,
      campaignId,
      style: { colour, pattern },
    })
    setBusy(false)
    if (!res.ok) {
      setError(res.body.message || "That did not work.")
      return
    }
    setName("")
    setDestination("")
    await reload()
  }

  return (
    <div>
      {allowance.limit !== 0 ? (
        <form className={s.create} onSubmit={create}>
          <h3 className={s.h3}>Make a trackable code</h3>
          <div className={s.fields}>
            <label className={s.field}>
              <span>Name</span>
              <input
                className={s.input}
                value={name}
                onChange={e => setName(e.target.value)}
                placeholder="Van, north route"
                maxLength={120}
                disabled={full}
              />
            </label>
            <label className={s.field}>
              <span>Where it goes</span>
              <input
                className={s.input}
                value={destination}
                onChange={e => setDestination(e.target.value)}
                placeholder="yourbusiness.com/spring-offer"
                disabled={full}
              />
            </label>
            <label className={s.field}>
              <span>Campaign (optional)</span>
              <select
                className={s.input}
                value={campaignId}
                onChange={e => setCampaignId(e.target.value)}
                disabled={full}
              >
                <option value="">No campaign</option>
                {campaigns.map(c => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </label>
            <label className={s.field}>
              <span>Pattern</span>
              <select
                className={s.input}
                value={pattern}
                onChange={e => setPattern(e.target.value)}
                disabled={full}
              >
                {PATTERNS.map(p => (
                  <option key={p.id} value={p.id}>
                    {p.label}
                  </option>
                ))}
              </select>
            </label>
          </div>

          <div className={s.swatches} role="radiogroup" aria-label="Colour">
            {SWATCHES.map(c => (
              <button
                key={c}
                type="button"
                role="radio"
                aria-checked={colour === c}
                aria-label={`Colour ${c}`}
                className={s.swatch}
                data-on={colour === c ? "true" : undefined}
                style={{ background: c }}
                onClick={() => setColour(c)}
                disabled={full}
              />
            ))}
          </div>

          <p className={s.hint}>
            A tracked code opens a web page. The code itself points at our address, which records
            the scan and then sends people on — so you can change where it goes later without
            reprinting anything.
          </p>

          {full ? (
            <p className={s.error}>
              Your plan includes {allowance.limit} trackable code{allowance.limit === 1 ? "" : "s"}{" "}
              and you have {allowance.used}. Delete one you no longer need, or move up a plan.
            </p>
          ) : null}

          <button type="submit" className={s.primaryBtn} disabled={busy || full}>
            {busy ? "Making it…" : "Create trackable code"}
          </button>
        </form>
      ) : null}

      {codes.length ? (
        <ul className={s.codes}>
          {codes.map(c => (
            <CodeRow key={c.id} code={c} campaigns={campaigns} reload={reload} setError={setError} />
          ))}
        </ul>
      ) : allowance.limit !== 0 ? (
        <p className={s.note}>No trackable codes yet. Make one above.</p>
      ) : null}
    </div>
  )
}

const TrackedQrs = () => {
  const [view, setView] = React.useState("codes")
  const [data, setData] = React.useState(null)
  const [error, setError] = React.useState("")

  const reload = React.useCallback(async () => {
    const res = await track({ action: "overview" })
    if (!res.ok) {
      setError(res.body.message || `Could not load your tracked codes (HTTP ${res.status}).`)
      return
    }
    setData(res.body)
  }, [])

  React.useEffect(() => {
    reload()
  }, [reload])

  if (!data) {
    return error ? (
      <>
        <p className={s.error}>{error}</p>
        <button type="button" className={s.small} onClick={reload}>
          Try again
        </button>
      </>
    ) : (
      <p className={s.note}>Loading your tracked codes…</p>
    )
  }

  return (
    <div className={s.wrap}>
      <Banner allowance={data.allowance} />

      {data.allowance.limit !== 0 ? (
        <div className={s.tabs} role="tablist" aria-label="Tracking">
          {TABS.map(t => (
            <button
              key={t.id}
              type="button"
              role="tab"
              aria-selected={view === t.id}
              className={s.tab}
              data-on={view === t.id ? "true" : undefined}
              onClick={() => setView(t.id)}
            >
              {t.label}
            </button>
          ))}
        </div>
      ) : null}

      {error ? <p className={s.error}>{error}</p> : null}

      {view === "codes" || data.allowance.limit === 0 ? (
        <CodesPanel data={data} reload={reload} setError={setError} />
      ) : null}
      {view === "insights" && data.allowance.limit !== 0 ? <TrackedInsights data={data} /> : null}
      {view === "campaigns" && data.allowance.limit !== 0 ? (
        <TrackedCampaigns data={data} reload={reload} setError={setError} />
      ) : null}
    </div>
  )
}

export default TrackedQrs
