import * as React from "react"
import PlanPicker from "./PlanPicker"
import * as s from "./Upsell.module.css"

/**
 * "Tracking is part of a paid plan" — FCS-100.
 * ============================================================================
 * It used to be a sentence and a button that went to the create-a-website
 * page, which answered a question nobody had asked. Somebody looking at a
 * locked feature wants three things, in this order: what would I get, what
 * else comes with it, and what does it cost and how do I get it.
 *
 *   1. The ADVERT. What tracking tells you — which advert, when, where — said
 *      the way the thing would be advertised, with a sample so it is concrete.
 *   2. The PLANS. Free, Premium and Lead Generation side by side, the way the
 *      rest of the product shows them, each with what is actually in it.
 *   3. The WAY THERE. Stripe, in one click.
 *
 * ── THE PLANS ARE SHARED ───────────────────────────────────────────────────
 * Prices, what each plan includes, and the way to Stripe live in PlanPicker,
 * which every "part of a paid plan" screen uses (FCS-101 added the invoices
 * one). The only invented text here is the sample scan log, and it is labelled
 * as an example.
 *
 * ── WHAT "WHO / WHEN / WHERE" MEANS ────────────────────────────────────────
 * Which ADVERT (each code is made for one van, flyer or sign), WHEN each scan
 * happened, and WHERE it was — the place if the person scanning allows it, the
 * country otherwise. It does not identify people and says nothing that implies
 * it does.
 */

const SAMPLE = [
  { advert: "Van door", where: "Dallas, TX", when: "Today, 9:42 AM", n: 3 },
  { advert: "Flyer drop, Oak Street", where: "Plano, TX", when: "Yesterday, 6:10 PM", n: 2 },
  { advert: "Yard sign", where: "Irving, TX", when: "Mon, 7:55 AM", n: 1 },
]

const TrackingUpsell = ({ currentPlan = "free" }) => {
  return (
    <section className={s.wrap} aria-label="Tracked QR codes are part of a paid plan" data-testid="tracking-upsell">
      {/* ── 1. the advert ── */}
      <div className={s.advert}>
        <div className={s.pitch}>
          <span className={s.kicker}>Tracked QR codes</span>
          <h3 className={s.headline}>Find out which advert actually brings the work in.</h3>
          <p className={s.copy}>
            An ordinary QR code just opens a page, and you never learn whether anyone used it. A
            tracked one counts every scan, so you can stop guessing which van, flyer or sign is
            earning its keep.
          </p>
          <ul className={s.points}>
            <li>
              <strong>Which advert.</strong> One code per van, flyer or sign, so each scan is
              credited to the one that earned it.
            </li>
            <li>
              <strong>When.</strong> The date and time of every scan, and a count over time.
            </li>
            <li>
              <strong>Where.</strong> A map of the places they were scanned, where the person
              allows it.
            </li>
          </ul>
        </div>

        <figure className={s.sample} aria-label="An example of the scan log">
          <figcaption className={s.sampleTag}>Example scan log</figcaption>
          <ul className={s.log}>
            {SAMPLE.map(row => (
              <li key={row.advert} className={s.logRow}>
                <span className={s.logAdvert}>{row.advert}</span>
                <span className={s.logMeta}>
                  {row.where} · {row.when}
                </span>
                <span className={s.logCount}>
                  {row.n} scan{row.n === 1 ? "" : "s"}
                </span>
              </li>
            ))}
          </ul>
          <p className={s.sampleNote}>
            Made-up numbers, to show the idea. Yours would be your own adverts and scans.
          </p>
        </figure>
      </div>

      {/* ── 2. more than a QR code ── */}
      <PlanPicker
        currentPlan={currentPlan}
        returnTo="qrs"
        badge="Includes QR tracking"
        title="It comes with more than a QR code"
        lead="A paid plan is a website on your own address, your invoices kept for you, and the tools that bring work in. Pick the one that fits."
      />
    </section>
  )
}

export default TrackingUpsell
