import * as React from "react"
import { emptyQr, qrOptions } from "../../lib/qr"

/**
 * A tracked code, drawn the way it was made — FCS-087.
 * ============================================================================
 * The same renderer and options as the QR studio, so a tracked code and a
 * plain one made with the same colour and pattern are indistinguishable.
 * What it encodes is the tracking URL, never the destination: the whole point
 * is that the code is printed once and the destination can change later.
 *
 * qr-code-styling reads `window`, so it is imported on demand, which also
 * keeps it out of Gatsby's static render.
 */
const TrackedQrImage = ({ url, style = {}, size = 112, instanceRef }) => {
  const holder = React.useRef(null)
  const made = React.useRef(null)

  React.useEffect(() => {
    let cancelled = false
    ;(async () => {
      const { default: QRCodeStyling } = await import("qr-code-styling")
      if (cancelled || !holder.current) return

      const options = qrOptions(
        {
          ...emptyQr(),
          kind: "url",
          value: url,
          colour: style.colour || "#0d1726",
          pattern: style.pattern || "rounded",
        },
        { size }
      )

      if (!made.current) made.current = new QRCodeStyling(options)
      else made.current.update(options)

      holder.current.innerHTML = ""
      made.current.append(holder.current)
      if (instanceRef) instanceRef.current = made.current
    })()
    return () => {
      cancelled = true
    }
  }, [url, style.colour, style.pattern, size, instanceRef])

  return <div ref={holder} style={{ width: size, height: size, lineHeight: 0 }} aria-hidden="true" />
}

export default TrackedQrImage
