import * as React from "react"
import { Link } from "gatsby"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"
import { InvoiceArt, QrArt } from "./EmptyArt"
import InvoicesUpsell from "./InvoicesUpsell"
import * as s from "./SavedDocuments.module.css"

/**
 * Invoices and QR codes somebody has kept — FCS-075.
 * ============================================================================
 * The Kelley Roads CMS pattern: a list of records with the thing you need to
 * recognise one on the left and what you can do with it on the right. One
 * component serves both kinds, because an invoice and a QR code differ only
 * in what the tool does with them after you press Open — the saving, naming,
 * listing and deleting are the same job twice.
 *
 * ── A LIST YOU CAN RECOGNISE SOMETHING IN ─────────────────────────────────
 * The name is theirs, typed by them, shown first and biggest. Not the
 * invoice number, not a slug, not "Invoice 4f2c8a" — somebody looking for
 * last Tuesday's kitchen job is looking for the words they used.
 *
 * ── EMPTY IS NOT BROKEN, AND NEITHER IS LOCKED ────────────────────────────
 * Three states that look alike and mean different things: nothing saved
 * yet, we could not ask, and your plan has no room left. Each gets its own
 * sentence, and only the last one has anything to do with money.
 *
 * ── EMPTY SHOWS WHAT WOULD BE HERE — FCS-106 ──────────────────────────────
 * "Nothing saved yet" beside a button is true and tells somebody nothing about
 * what the screen is for. The empty state now draws the thing that would be in
 * it (a QR code, an invoice), says in three steps how it gets there, and has
 * one button. It keeps the old sentence word for word, so anything that looked
 * for it still finds it.
 *
 * ── A PLAN THAT DOES NOT KEEP THEM GETS AN UPSELL — FCS-101 ───────────────
 * When the plan's cap for invoices is 0, "Nothing saved yet. Build an invoice
 * and press Save" is a lie: pressing Save would be refused. The screen shows
 * what keeping invoices gets you instead, with the plans and the way to Stripe.
 * Somebody who saved some before the cap (or while on a plan that kept them)
 * still sees and can manage those, with the upsell beneath.
 *
 * ── DELETING ASKS ─────────────────────────────────────────────────────────
 * Once, inline, on the row itself rather than in a modal. There is no undo
 * behind this and no copy anywhere else, so a mis-click costs somebody their
 * work.
 */

const KINDS = {
  invoice: {
    plural: "invoices",
    one: "invoice",
    tool: "/invoice-builder/",
    toolLabel: "Invoice builder",
    button: "Open the invoice builder",
    blank: "Nothing saved yet. Build an invoice and press Save to keep it here.",
    intro: "Build an invoice and press Save to keep it here.",
    emptyTitle: "Your saved invoices will live here",
    steps: ["Build an invoice", "Press Save", "Find it here, and open it any time"],
  },
  qr: {
    plural: "QR codes",
    one: "QR code",
    tool: "/qr-codes/",
    toolLabel: "QR codes",
    button: "Make a QR code",
    blank: "Nothing saved yet. Make a QR code and press Save to keep it here.",
    intro: "Make a QR code and press Save to keep it here.",
    emptyTitle: "Your saved QR codes will live here",
    steps: ["Make a QR code", "Press Save", "Find it here, and open it any time"],
  },
}

const call = async body => {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token

  const res = await fetch(apiUrl("my-documents"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
    },
    body: JSON.stringify(body),
  })
  return { ok: res.ok, status: res.status, body: await res.json().catch(() => ({})) }
}

const when = value => {
  if (!value) return ""
  const d = new Date(value)
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleDateString()
}

const SavedDocuments = ({ kind }) => {
  const meta = KINDS[kind] || KINDS.invoice
  const [docs, setDocs] = React.useState(null)
  // What the plan keeps for this kind: { plan, limit, used }; limit 0 means none.
  const [allowance, setAllowance] = React.useState(null)
  const [error, setError] = React.useState("")
  const [busy, setBusy] = React.useState("")
  const [confirming, setConfirming] = React.useState("")
  const [renaming, setRenaming] = React.useState("")
  const [draftName, setDraftName] = React.useState("")

  const load = React.useCallback(async () => {
    setError("")
    const res = await call({ action: "list", kind })
    if (!res.ok) {
      setError(res.body.message || `Could not load your ${meta.plural}.`)
      setDocs([])
      return
    }
    setDocs(res.body.documents || [])
    setAllowance(res.body.allowance || null)
  }, [kind, meta.plural])

  React.useEffect(() => {
    setDocs(null)
    load()
  }, [load])

  const remove = async id => {
    setBusy(id)
    const res = await call({ action: "delete", id })
    setBusy("")
    setConfirming("")
    if (!res.ok) {
      setError(res.body.message || "That could not be deleted.")
      return
    }
    setDocs(list => list.filter(d => d.id !== id))
  }

  const rename = async id => {
    const name = draftName.trim()
    if (!name) return
    setBusy(id)
    const res = await call({ action: "rename", id, name })
    setBusy("")
    setRenaming("")
    if (!res.ok) {
      setError(res.body.message || "That could not be renamed.")
      return
    }
    setDocs(list => list.map(d => (d.id === id ? { ...d, name } : d)))
  }

  /* ── THE INTRO IS THERE FROM THE FIRST FRAME — FCS-111 ───────────────────
     The QR screen draws its picture, three steps and button straight away, and
     whatever is saved appears BELOW it ("make this appear while loading … then
     have any saved appear below it"). It is the same element in every state, so
     it never remounts or flickers when the answer arrives.
     Invoices stay as they were: until the plan's answer is in we cannot tell the
     intro from the upsell, and drawing the wrong one first is worse than a line. */
  const keepsIntro = kind === "qr"
  if (docs === null && !keepsIntro) return <p className={s.note}>Loading your {meta.plural}…</p>
  const loading = docs === null
  const list = docs || []

  // The plan does not keep these, and there is nothing here: show what it would get them.
  const notKept = kind === "invoice" && allowance?.limit === 0
  if (notKept && list.length === 0 && !error) {
    return <InvoicesUpsell currentPlan={allowance.plan} />
  }

  return (
    <div className={s.wrap}>
      {keepsIntro || list.length === 0 ? (
        <div className={s.empty} data-testid={!loading && list.length === 0 ? "saved-empty" : "saved-intro"}>
          <div className={s.art}>{kind === "qr" ? <QrArt /> : <InvoiceArt />}</div>
          <div className={s.emptyText}>
            <h3 className={s.emptyTitle}>{meta.emptyTitle}</h3>
            <p className={s.emptyNote}>{loading || list.length > 0 ? meta.intro : meta.blank}</p>
            <ol className={s.steps}>
              {meta.steps.map(step => (
                <li key={step}>{step}</li>
              ))}
            </ol>
            <Link className={s.primary} to={meta.tool}>
              {meta.button}
            </Link>
          </div>
        </div>
      ) : (
        <div className={s.head}>
          <p className={s.note}>
            {`${list.length} saved ${list.length === 1 ? meta.one : meta.plural}.${notKept ? " Saving new ones is part of a paid plan." : ""}`}
          </p>
          <Link className={s.primary} to={meta.tool}>
            {meta.button}
          </Link>
        </div>
      )}

      {/* Under the intro: the saved codes. While we ask, two placeholder rows hold their place. */}
      {keepsIntro && loading ? (
        <ul className={s.list} aria-busy="true" aria-label="Loading your saved QR codes" data-testid="saved-skeleton">
          <li className={s.skelItem} />
          <li className={s.skelItem} />
        </ul>
      ) : null}
      {keepsIntro && !loading && list.length > 0 ? (
        <p className={s.listNote}>{`${list.length} saved ${list.length === 1 ? meta.one : meta.plural}.`}</p>
      ) : null}

      {error ? <p className={s.error}>{error}</p> : null}

      {list.length > 0 ? (
        <ul className={s.list}>
          {list.map(doc => (
            <li key={doc.id} className={s.item} data-busy={busy === doc.id ? "true" : undefined}>
              {renaming === doc.id ? (
                <form
                  className={s.renameRow}
                  onSubmit={event => {
                    event.preventDefault()
                    rename(doc.id)
                  }}
                >
                  <input
                    className={s.input}
                    value={draftName}
                    onChange={event => setDraftName(event.target.value)}
                    aria-label={`Rename ${doc.name}`}
                    maxLength={120}
                    autoFocus
                  />
                  <button type="submit" className={s.small}>
                    Save
                  </button>
                  <button type="button" className={s.small} onClick={() => setRenaming("")}>
                    Cancel
                  </button>
                </form>
              ) : (
                <>
                  <span className={s.text}>
                    <span className={s.name}>{doc.name}</span>
                    <span className={s.meta}>
                      Saved {when(doc.createdAt)}
                      {doc.updatedAt && doc.updatedAt !== doc.createdAt
                        ? ` · changed ${when(doc.updatedAt)}`
                        : ""}
                    </span>
                  </span>

                  <span className={s.row}>
                    {/* The tool opens it — the list's job is finding it, not
                        editing it. */}
                    <Link className={s.small} to={`${meta.tool}?open=${doc.id}`}>
                      Open
                    </Link>
                    <button
                      type="button"
                      className={s.small}
                      onClick={() => {
                        setRenaming(doc.id)
                        setDraftName(doc.name)
                      }}
                    >
                      Rename
                    </button>

                    {/* Asked once, on the row. No undo behind this. */}
                    {confirming === doc.id ? (
                      <>
                        <button
                          type="button"
                          className={`${s.small} ${s.danger}`}
                          onClick={() => remove(doc.id)}
                          disabled={busy === doc.id}
                        >
                          {busy === doc.id ? "Deleting…" : "Delete for good"}
                        </button>
                        <button
                          type="button"
                          className={s.small}
                          onClick={() => setConfirming("")}
                        >
                          Keep
                        </button>
                      </>
                    ) : (
                      <button
                        type="button"
                        className={s.small}
                        onClick={() => setConfirming(doc.id)}
                      >
                        Delete
                      </button>
                    )}
                  </span>
                </>
              )}
            </li>
          ))}
        </ul>
      ) : null}

      {notKept && list.length > 0 ? <InvoicesUpsell currentPlan={allowance.plan} /> : null}
    </div>
  )
}

export default SavedDocuments
