import * as React from "react"
import { Link, navigate } from "gatsby"
import Header from "../Header"
import { ArrowRight } from "../Icons"
import AffiliateAdverts from "./AffiliateAdverts"
import { useAuth } from "../../context/auth"
import { useAffiliateReport } from "../../lib/affiliate-report"
import { rememberName } from "../../lib/display-name"
import { AFFILIATE_MESSAGES } from "../../lib/affiliate"
import { CURRENCY } from "../../config/project"
import * as s from "../account/Dashboard.module.css"

/**
 * An affiliate's own account — FCS-110.
 * ============================================================================
 * Nate, logged in as an affiliate: "The only things that should be in the
 * affiliate dashboard are Dashboard, Affiliate, Billing, Settings."
 *
 * Until now an affiliate who clicked Account got the CONTRACTOR screen — Website,
 * Invoices, QR codes, Leads — because every login lands on the same page. An
 * affiliate is not a contractor (see lib/affiliate.js): they make adverts and are
 * paid for the sign-ups those bring, so those four things are all they are shown.
 *
 * It wears the same frame as the contractor account (same sidebar, same cards) so
 * it reads as one product, and `account.js` decides which of the two to render.
 */

const NAV = [
  { id: "dashboard", label: "Dashboard" },
  { id: "affiliate", label: "Affiliate" },
  { id: "billing", label: "Billing" },
  { id: "settings", label: "Settings" },
]

const HEADS = {
  dashboard: { title: "Dashboard", lead: "How your adverts are doing, at a glance." },
  affiliate: { title: "Affiliate", lead: "Make adverts, and see which ones and which groups brought people in." },
  billing: { title: "Billing", lead: "What you earn. Nothing is ever charged to an affiliate account." },
  settings: { title: "Settings", lead: "The details we have for you." },
}

/* The same line-icon weight as the contractor menu. */
const PATHS = {
  dashboard: "M3 3h6v6H3zM11 3h6v6h-6zM3 11h6v6H3zM11 11h6v6h-6z",
  affiliate: "M3 8.5v3l10 4.5V4L3 8.5zM13 7.5h2a2 2 0 0 1 0 5h-2M5.5 12.5 6.5 17h2l-.8-3.2",
  billing: "M2 6h16v9H2zM2 9h16M5 12.5h3",
  settings:
    "M10 12.5a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5zM10 2.5v2M10 15.5v2M3.5 10h-2M18.5 10h-2M5.4 5.4 4 4M16 16l-1.4-1.4M14.6 5.4 16 4M4 16l1.4-1.4",
}

const Icon = ({ name }) => (
  <svg
    className={s.navIcon}
    viewBox="0 0 20 20"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.6"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d={PATHS[name]} />
  </svg>
)

const Tile = ({ label, value, note }) => (
  <div className={s.tile}>
    <span className={s.tileLabel}>{label}</span>
    <span className={s.tileValue}>{value}</span>
    {note ? <span className={s.tileNote}>{note}</span> : null}
  </div>
)

const STATUS_WORDS = { active: "Approved", pending: "Waiting for approval", paused: "Paused" }

const money = cents =>
  new Intl.NumberFormat("en-US", { style: "currency", currency: CURRENCY.toUpperCase() }).format(cents / 100)

const sectionFromHash = () => {
  if (typeof window === "undefined") return "dashboard"
  const wanted = window.location.hash.replace("#", "")
  return NAV.some(n => n.id === wanted) ? wanted : "dashboard"
}

const AffiliateAccount = ({ location }) => {
  const { user, affiliate, signOut } = useAuth()
  const [section, setSection] = React.useState("dashboard")

  /* The address says where you are (/account/#affiliate), so a link or a reload lands
     back on the same screen — and `hashchange` covers a second link to this page. */
  React.useEffect(() => {
    const apply = () => setSection(sectionFromHash())
    apply()
    window.addEventListener("hashchange", apply)
    return () => window.removeEventListener("hashchange", apply)
  }, [location?.hash])

  const show = id => {
    setSection(id)
    try {
      window.history.replaceState(null, "", `${window.location.pathname}${id === "dashboard" ? "" : `#${id}`}`)
      window.scrollTo(0, 0)
    } catch {
      /* the screen still changed; only the address did not */
    }
  }

  /* A pending application has nothing to report yet; anyone else may still have
     adverts out there that are counting. */
  const counting = affiliate?.status === "active" || affiliate?.status === "paused"
  const { report, error, busy, load } = useAffiliateReport(counting)

  const status = affiliate?.status || "active"
  const email = affiliate?.email || user?.email || ""
  const name = affiliate?.name || ""
  const totals = report?.totals || { visits: 0, sales: 0, rate: 0 }
  const waiting = !report && counting && !error
  const dash = "—"
  const rate = affiliate?.rate_cents
  const notice = status === "pending" || status === "paused" ? AFFILIATE_MESSAGES[status] : null

  // The header greets them by name (FCS-113).
  React.useEffect(() => {
    if (user?.id && affiliate?.name) rememberName(user.id, affiliate.name)
  }, [user?.id, affiliate?.name])

  const logOut = () => signOut().then(() => navigate("/"))

  return (
    <>
      <Header />
      <main className={s.page}>
        <div className="container">
          <div className={s.shell}>
            <div className={s.sideCol}>
              <aside className={s.side}>
                <div className={s.who}>
                  <span className={s.avatar} aria-hidden="true">
                    {(name || email || "?")[0].toUpperCase()}
                  </span>
                  <span className={s.whoText}>
                    <span className={s.whoName}>{name || email || "Your account"}</span>
                    <span className={s.whoPlan}>Affiliate</span>
                  </span>
                </div>

                <nav className={s.nav} aria-label="Account sections" data-testid="affiliate-nav">
                  {NAV.map(item => (
                    <button
                      key={item.id}
                      type="button"
                      className={s.navItem}
                      aria-current={section === item.id ? "true" : undefined}
                      onClick={() => show(item.id)}
                    >
                      <Icon name={item.id} />
                      {item.label}
                    </button>
                  ))}
                </nav>

                <div className={s.sideFoot}>
                  <button type="button" className={`${s.ghost} ${s.wide}`} onClick={logOut}>
                    Log out
                  </button>
                </div>
              </aside>
            </div>

            <div className={s.panel}>
              <div className={s.panelHead}>
                <h1 className={s.title}>{HEADS[section].title}</h1>
                <p className={s.lead}>{HEADS[section].lead}</p>
              </div>

              {error ? <p className={s.error}>{error}</p> : null}

              {section === "dashboard" ? (
                <>
                  {notice ? (
                    <section className={s.card}>
                      <div className={s.cardHead}>
                        <h2 className={s.cardTitle}>{notice.title}</h2>
                      </div>
                      <p className={s.note}>{notice.body}</p>
                    </section>
                  ) : null}

                  <div className={s.tiles}>
                    <Tile label="Visits" value={waiting ? dash : totals.visits} note="people who scanned or clicked" />
                    <Tile
                      label="Sales"
                      value={waiting ? dash : totals.sales}
                      note={waiting ? "they went on to buy" : `${totals.rate}% of visits`}
                    />
                    <Tile label="Adverts" value={waiting ? dash : report?.codes?.length ?? 0} note="you have made" />
                  </div>

                  {status === "active" ? (
                    <section className={s.card}>
                      <div className={s.cardHead}>
                        <h2 className={s.cardTitle}>Your adverts</h2>
                      </div>
                      <p className={s.note}>
                        Make an advert with a QR code that carries your code, post it in a group, and every visit
                        and sale it brings is counted here.
                      </p>
                      <div className={s.actions}>
                        <Link to="/ad-studio" className={s.primary}>
                          Make an advert
                          <ArrowRight className="btn__arrow" />
                        </Link>
                        <button type="button" className={s.ghost} onClick={() => show("affiliate")}>
                          See how they did
                        </button>
                      </div>
                    </section>
                  ) : null}
                </>
              ) : null}

              {section === "affiliate" ? (
                <>
                  {status === "active" ? (
                    <div className={s.actions}>
                      <Link to="/ad-studio" className={s.primary}>
                        Make another advert
                        <ArrowRight className="btn__arrow" />
                      </Link>
                    </div>
                  ) : null}
                  {counting ? (
                    <AffiliateAdverts report={report} busy={busy} onRefresh={load} />
                  ) : (
                    <p className={s.note}>{AFFILIATE_MESSAGES.pending.body}</p>
                  )}
                </>
              ) : null}

              {section === "billing" ? (
                <section className={s.card}>
                  <div className={s.cardHead}>
                    <h2 className={s.cardTitle}>What you earn</h2>
                  </div>
                  <dl className={s.facts}>
                    <div>
                      <dt>Per sale</dt>
                      <dd>{rate == null ? "Agreed with you directly" : money(rate)}</dd>
                    </div>
                    <div>
                      <dt>Sales counted</dt>
                      <dd>{waiting ? dash : totals.sales}</dd>
                    </div>
                    {rate != null ? (
                      <div>
                        <dt>Earned so far</dt>
                        <dd>{waiting ? dash : money(rate * totals.sales)}</dd>
                      </div>
                    ) : null}
                  </dl>
                  <p className={s.note}>
                    A sale is counted when the customer&apos;s payment goes through. You pay nothing to be an
                    affiliate, and nothing is taken from you here. If a payment looks wrong, get in touch.
                  </p>
                </section>
              ) : null}

              {section === "settings" ? (
                <section className={s.card}>
                  <div className={s.cardHead}>
                    <h2 className={s.cardTitle}>Your details</h2>
                  </div>
                  <dl className={s.facts}>
                    <div>
                      <dt>Name</dt>
                      <dd>{name || dash}</dd>
                    </div>
                    <div>
                      <dt>Email</dt>
                      <dd>{email || dash}</dd>
                    </div>
                    <div>
                      <dt>Status</dt>
                      <dd>{STATUS_WORDS[status] || status}</dd>
                    </div>
                  </dl>
                  <p className={s.note}>
                    To change any of these, get in touch.
                  </p>
                </section>
              ) : null}
            </div>
          </div>
        </div>
      </main>
    </>
  )
}

export default AffiliateAccount
