import * as React from "react"

/**
 * Pictures for empty screens — FCS-106.
 * ============================================================================
 * "Nothing saved yet" next to a button is accurate and dull: it tells somebody
 * the screen is empty and shows them nothing of what would be in it. These are
 * the things that WOULD be there, drawn small: a QR code, an invoice.
 *
 * Inline SVG, not an image file: nothing to load (so nothing to pop in), it
 * takes the site's blue, and it is the same sharp at any size. They are
 * decoration, so `aria-hidden`; the words beside them carry the meaning.
 *
 * ── THE QR IS A DRAWING OF ONE, NOT A WORKING ONE ──────────────────────────
 * Three finder squares and a fixed scatter of dots. It will not scan, and is
 * not meant to: a code that scanned would point somewhere, and an illustration
 * should not. The pattern is a fixed list, not random, so it is the same on
 * every render and every build.
 */

const BLUE = "#1668e8"
const INK = "#0d1726"

// A 17 x 17 grid; "1" is a dark module. The three 7 x 7 corners are drawn separately.
const DOTS = [
  "00000000011010000",
  "00000000100101000",
  "00000000011011000",
  "00000000101100000",
  "00000000010111000",
  "00000000001001000",
  "00000000110110000",
  "01011010011010101",
  "10100101100101010",
  "01101011011010110",
  "11010100101101001",
  "00101101010010110",
  "01010010110101011",
  "10110101001101100",
  "00011010110010101",
  "01101100011011010",
  "10010011100101001",
]

const finder = (x, y) => (
  <g transform={`translate(${x} ${y})`}>
    <rect width="7" height="7" rx="1.4" fill={INK} />
    <rect x="1" y="1" width="5" height="5" rx="0.9" fill="#fff" />
    <rect x="2" y="2" width="3" height="3" rx="0.6" fill={BLUE} />
  </g>
)

export const QrArt = () => (
  <svg viewBox="0 0 120 120" width="120" height="120" aria-hidden="true" focusable="false">
    <rect x="2" y="2" width="116" height="116" rx="16" fill="#fff" stroke="#dbe5f4" strokeWidth="2" />
    <g transform="translate(17 17) scale(5.1)">
      {DOTS.flatMap((row, y) =>
        [...row].map((cell, x) => {
          const inCorner = (x < 7 && y < 7) || (x > 9 && y < 7) || (x < 7 && y > 9)
          return cell === "1" && !inCorner ? (
            <rect key={`${x}-${y}`} x={x + 0.08} y={y + 0.08} width="0.84" height="0.84" rx="0.2" fill={INK} />
          ) : null
        })
      )}
      {finder(0, 0)}
      {finder(10, 0)}
      {finder(0, 10)}
    </g>
    {/* the line a scanner would draw across it */}
    <rect className="scanLine" x="12" y="58" width="96" height="3" rx="1.5" fill={BLUE} opacity="0.85" />
  </svg>
)

export const InvoiceArt = () => (
  <svg viewBox="0 0 120 140" width="112" height="131" aria-hidden="true" focusable="false">
    <rect x="3" y="3" width="114" height="134" rx="12" fill="#fff" stroke="#dbe5f4" strokeWidth="2" />
    <rect x="14" y="14" width="92" height="22" rx="6" fill={INK} />
    <rect x="22" y="21" width="36" height="8" rx="3" fill="#fff" />
    <rect x="14" y="44" width="40" height="6" rx="3" fill="#c9d6ea" />
    <rect x="14" y="56" width="60" height="5" rx="2.5" fill="#e3eaf5" />
    {[72, 84, 96].map(y => (
      <g key={y}>
        <rect x="14" y={y} width="50" height="5" rx="2.5" fill="#e3eaf5" />
        <rect x="80" y={y} width="26" height="5" rx="2.5" fill="#c9d6ea" />
      </g>
    ))}
    <rect x="58" y="110" width="48" height="18" rx="6" fill={BLUE} />
    <rect x="66" y="116" width="32" height="6" rx="3" fill="#fff" />
  </svg>
)
