import * as React from "react"
import { Link } from "gatsby"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"
import { emptyDraft, loadDraft } from "../../lib/site-draft"
import * as d from "./Dashboard.module.css"
import * as s from "./PathPagePanel.module.css"

/**
 * A free page at freecontractorservices.com/their-name — FCS-118.
 * ============================================================================
 * Nate: "sign up and create an account … then login and set up a
 * {our-domain}/their-url page." This is that screen: pick a name, see at once
 * whether it is free, press Publish, get the link.
 *
 * ── WHAT GETS PUBLISHED ────────────────────────────────────────────────────
 * The website they built in the builder, if they have started one on this device;
 * otherwise a plain page from the three fields below (business name, phone, what
 * they do), so somebody who has not been near the builder still ends up with a
 * page that opens. Either way the server decides the plan (always free) and who
 * may use the address; nothing here is trusted for either.
 *
 * ── ONE PAGE PER ACCOUNT ───────────────────────────────────────────────────
 * Once there is a page the address is fixed and this becomes "update it": the
 * same address, new content. Moving it is a support job, not a text box.
 */

const APEX = "freecontractorservices.com"

const headers = async () => {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  return {
    "Content-Type": "application/json",
    apikey: SUPABASE_PUBLISHABLE_KEY,
    Authorization: `Bearer ${data?.session?.access_token || SUPABASE_PUBLISHABLE_KEY}`,
  }
}

/** What somebody types, made into an address: lowercase, spaces and strays become single hyphens. */
const tidy = value =>
  String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, "-")
    .replace(/-{2,}/g, "-")
    .replace(/^-+/, "")
    .slice(0, 50)

const PathPagePanel = ({ site, onPublished }) => {
  const mine = site?.placement === "path" ? site.subdomain.replace(/^path--/, "") : ""
  const [slug, setSlug] = React.useState(mine)
  const [avail, setAvail] = React.useState({ state: mine ? "mine" : "idle", reason: "" })
  const [draft, setDraft] = React.useState(null)
  const [fields, setFields] = React.useState({ name: "", phone: "", tagline: "" })
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState("")
  const [live, setLive] = React.useState(null)

  // The builder's draft lives in this browser only; it is read after mount.
  React.useEffect(() => {
    const saved = loadDraft()
    setDraft(saved?.business?.name?.trim() ? saved : null)
  }, [])

  React.useEffect(() => {
    if (mine) setSlug(mine)
  }, [mine])

  // Is the address free? Asked as they type, once they stop.
  React.useEffect(() => {
    if (mine) return undefined
    if (!slug) {
      setAvail({ state: "idle", reason: "" })
      return undefined
    }
    setAvail({ state: "checking", reason: "" })
    const controller = new AbortController()
    const timer = window.setTimeout(async () => {
      try {
        const res = await fetch(apiUrl("subdomain-available"), {
          method: "POST",
          headers: await headers(),
          body: JSON.stringify({ slug, placement: "path" }),
          signal: controller.signal,
        })
        const body = await res.json()
        if (body.available === true) setAvail({ state: "free", reason: "" })
        else if (body.available === false) setAvail({ state: "taken", reason: body.reason || "That address is not available." })
        else setAvail({ state: "unknown", reason: body.reason || "We could not check that address." })
      } catch (err) {
        if (err.name !== "AbortError") setAvail({ state: "unknown", reason: "We could not check that address." })
      }
    }, 400)
    return () => {
      window.clearTimeout(timer)
      controller.abort()
    }
  }, [slug, mine])

  const ready = Boolean(slug) && (mine || avail.state === "free") && (draft || fields.name.trim())

  const publish = async event => {
    event.preventDefault()
    if (!ready || busy) return
    setBusy(true)
    setError("")
    const base = emptyDraft()
    const content =
      draft || {
        ...base,
        business: { ...base.business, name: fields.name.trim(), phone: fields.phone.trim(), tagline: fields.tagline.trim() },
      }
    try {
      const res = await fetch(apiUrl("publish-site"), {
        method: "POST",
        headers: await headers(),
        body: JSON.stringify({ slug, placement: "path", draft: content }),
      })
      const body = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(body.message || `That could not be published (HTTP ${res.status}).`)
        return
      }
      setLive(body.url)
      if (onPublished) onPublished()
    } catch {
      setError("We could not reach the server. Check your connection and try again.")
    } finally {
      setBusy(false)
    }
  }

  const note =
    avail.state === "checking"
      ? "Checking…"
      : avail.state === "free"
        ? "That address is free."
        : avail.state === "mine"
          ? "This is your address."
          : avail.reason

  return (
    <section className={d.card} data-testid="path-page-panel">
      <div className={d.cardHead}>
        <h2 className={d.cardTitle}>{mine ? "Your free page" : "Put a free page online"}</h2>
      </div>
      <p className={d.note}>
        {mine
          ? "Change what is on it and publish again. The address stays the same."
          : `A page of your own at ${APEX}/your-name. It is free, it goes live as soon as you press Publish, and you can change it any time.`}
      </p>

      <form onSubmit={publish}>
        <label className={s.label} htmlFor="pp-slug">
          Your address
        </label>
        <div className={s.addr}>
          <span className={s.prefix}>{APEX}/</span>
          <input
            id="pp-slug"
            className={s.input}
            value={slug}
            readOnly={Boolean(mine)}
            placeholder="your-business"
            autoComplete="off"
            spellCheck="false"
            maxLength={50}
            onChange={e => setSlug(tidy(e.target.value))}
          />
        </div>
        <p className={s.status} data-state={avail.state} role="status" data-testid="path-page-status">
          {note}
        </p>

        {draft ? (
          <p className={d.note} data-testid="path-page-draft">
            This publishes the website you built: <strong>{draft.business.name}</strong>.{" "}
            <Link to="/website-builder">Change it in the builder</Link> first if you want to.
          </p>
        ) : (
          <div className={s.fields}>
            <div className={s.field}>
              <label htmlFor="pp-name">Business name</label>
              <input id="pp-name" value={fields.name} maxLength={80} onChange={e => setFields({ ...fields, name: e.target.value })} />
            </div>
            <div className={s.field}>
              <label htmlFor="pp-phone">Phone (optional)</label>
              <input id="pp-phone" type="tel" value={fields.phone} maxLength={30} onChange={e => setFields({ ...fields, phone: e.target.value })} />
            </div>
            <div className={`${s.field} ${s.wide}`}>
              <label htmlFor="pp-tagline">What you do (optional)</label>
              <input id="pp-tagline" value={fields.tagline} maxLength={120} placeholder="Roofing and repairs in Austin" onChange={e => setFields({ ...fields, tagline: e.target.value })} />
            </div>
            <p className={`${s.wide} ${d.note}`}>
              Want more on it — your services, photos, the areas you cover? <Link to="/website-builder">Build it in the builder</Link>, then come back and publish.
            </p>
          </div>
        )}

        {error ? <p className={d.error}>{error}</p> : null}

        <div className={d.actions}>
          <button type="submit" className={d.primary} disabled={!ready || busy}>
            {busy ? "Publishing…" : mine ? "Publish changes" : "Publish my page"}
          </button>
        </div>
      </form>

      {live ? (
        <p className={s.live} role="status" data-testid="path-page-live">
          Your page is live:{" "}
          <a href={live} target="_blank" rel="noreferrer">
            {live.replace(/^https:\/\//, "")}
          </a>
        </p>
      ) : null}
    </section>
  )
}

export default PathPagePanel
