import * as React from "react"
import { Link } from "gatsby"
import { formatMoney } from "../../config/pricing"
import { TIERS } from "../../data/plans"
import { useAuth } from "../../context/auth"
import { ArrowRight } from "../Icons"
import PlanPicker, { featuresFor, openStripe } from "./PlanPicker"
import * as b from "./BillingPanel.module.css"

/**
 * Billing — FCS-108.
 * ============================================================================
 * It was a card with a plan name, "No charge", two small facts and a button.
 * Billing is where somebody goes to answer three questions, so it now answers
 * them in order:
 *
 *   1. WHAT AM I ON?       the plan, its price, and whether it is in good order
 *   2. WHAT DOES THAT GET ME?   the list, read from the plan data
 *   3. WHAT ELSE IS THERE, AND HOW DO I MOVE?   the plans side by side, with the
 *      way to Stripe — Checkout from Free, the billing portal for somebody who
 *      already pays
 *
 * ── THE LIST AND THE PRICES ARE THE PLAN DATA ──────────────────────────────
 * Nothing on this screen is typed in: what a plan includes comes from
 * src/data/plans.js and what it costs from the same place, so it cannot promise
 * what the checkout does not sell.
 *
 * ── THE STATUS IS IN WORDS ─────────────────────────────────────────────────
 * "past_due" is what the database says; "Payment overdue" is what a person
 * needs to read. An unfamiliar value is shown as it is rather than hidden.
 */

const STATUS = {
  free: ["Free", "neutral"],
  active: ["Active", "good"],
  paid: ["Paid", "good"],
  trialing: ["On trial", "good"],
  past_due: ["Payment overdue", "warn"],
  pending_payment: ["Waiting for payment", "warn"],
  cancelled: ["Cancelled", "bad"],
  canceled: ["Cancelled", "bad"],
}

const statusOf = value => STATUS[String(value || "").toLowerCase()] || [value || "—", "neutral"]

/** Everything the plan includes: Lead Generation's list builds on Premium's. */
const includedIn = id => {
  if (id === "free") return featuresFor("free").items
  if (id === "premium") return featuresFor("premium").items
  return [...featuresFor("premium").items, ...featuresFor("leads").items]
}

/** `plan` { id, name, amount, interval }, `status` the account's words, `since` already formatted. */
const BillingPanel = ({ plan, status, since, recoveryCode }) => {
  const { user } = useAuth()
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState("")

  const paying = plan.amount > 0
  const [statusWord, statusTone] = statusOf(status)
  const tagline = TIERS[plan.id]?.tagline || ""

  const manage = async () => {
    setBusy(true)
    setError("")
    const result = await openStripe({ kind: "portal", email: user?.email || "" })
    if (result.ok) {
      window.location.assign(result.url)
      return
    }
    setError(result.message)
    setBusy(false)
  }

  return (
    <div className={b.wrap} data-testid="billing" data-plan={plan.id}>
      {/* ── 1. what am I on ── */}
      <section className={b.hero}>
        <div className={b.heroMain}>
          <span className={b.kicker}>Your plan</span>
          <h2 className={b.planName}>{plan.name}</h2>
          <p className={b.price}>
            {paying ? (
              <>
                <strong>{formatMoney(plan.amount)}</strong> a {plan.interval}
              </>
            ) : (
              <>
                <strong>$0</strong> — no charge
              </>
            )}
          </p>
          {tagline ? <p className={b.tagline}>{tagline}</p> : null}
        </div>

        <dl className={b.facts}>
          <div>
            <dt>Status</dt>
            <dd>
              <span className={b.status} data-tone={statusTone}>
                {statusWord}
              </span>
            </dd>
          </div>
          {since ? (
            <div>
              <dt>Member since</dt>
              <dd className={b.since}>{since}</dd>
            </div>
          ) : null}
        </dl>
      </section>

      {/* ── 2. what does that get me ── */}
      <section className={b.card}>
        <h3 className={b.cardTitle}>What {plan.name} includes</h3>
        <ul className={b.includes}>
          {includedIn(plan.id).map(item => (
            <li key={item}>{item}</li>
          ))}
        </ul>

        <div className={b.actions}>
          {paying ? (
            <button type="button" className={b.primary} onClick={manage} disabled={busy}>
              {busy ? "Opening Stripe…" : "Manage billing in Stripe"}
            </button>
          ) : (
            <Link to="/website-builder" className={b.primary}>
              Put my site online
              <ArrowRight className="btn__arrow" />
            </Link>
          )}
          <Link to="/help/cannot-log-in" className={b.ghost}>
            Billing help
          </Link>
        </div>
        {error ? (
          <p className={b.error} role="alert">
            {error}
          </p>
        ) : null}

        {/* Said here because this is where somebody looks for it, and it is the
            only thread back to a payment if they lose their email address. */}
        {recoveryCode ? (
          <p className={b.recovery}>
            Your recovery code is <strong className={b.mono}>{recoveryCode}</strong>. Keep it — it is
            how we find your payment if you cannot log in.
          </p>
        ) : null}
      </section>

      {/* ── 3. what else is there ── */}
      <section className={b.compare} aria-label="Compare plans">
        <PlanPicker
          currentPlan={plan.id}
          returnTo="billing"
          title="Compare plans"
          lead={
            paying
              ? "Change plan, update your card or cancel any time in Stripe. Nothing here is a contract."
              : "Upgrade when you are ready. You can cancel whenever you like."
          }
        />
      </section>
    </div>
  )
}

export default BillingPanel
