import * as React from "react"
import AdGallery from "../ads/AdGallery"
import * as s from "../admin/Admin.module.css"

/**
 * Which adverts and which groups worked — MTC-FCS-041 / FCS-072, moved out of
 * the /affiliate page for FCS-110 so the account screen can show it.
 *
 * One row per code, and one per group, because they answer different questions:
 * the code says which image and wording worked, the group says where to post next.
 */

const when = value => (value ? new Date(value).toLocaleDateString() : "—")

const AffiliateAdverts = ({ report, busy, onRefresh }) => (
  <>
    {/* The pictures first: "which one was that" comes before "which performed best". */}
    <AdGallery codes={report?.codes || []} />

    <div className={s.card}>
      <div className={s.head}>
        <h2 className={s.cardTitle}>Which adverts worked</h2>
        <button type="button" className={`${s.button} ${s.ghost}`} onClick={onRefresh} disabled={busy}>
          {busy ? "Loading…" : "Refresh"}
        </button>
      </div>

      {!report ? (
        <p className={s.note}>Loading…</p>
      ) : report.codes.length === 0 ? (
        <p className={s.note}>
          {report.message || "Nothing yet."} Codes only count once they are saved while you are logged in.
        </p>
      ) : (
        <div className={s.scroll}>
          <table className={s.table}>
            <thead>
              <tr>
                <th>Code</th>
                <th>Posted in</th>
                <th>Advert</th>
                <th>Visits</th>
                <th>Sales</th>
                <th>Rate</th>
                <th>Came from</th>
                <th>Last activity</th>
              </tr>
            </thead>
            <tbody>
              {report.codes.map(row => (
                <tr key={row.code}>
                  <td className={s.mono}>{row.code}</td>
                  <td>{row.placedIn || "—"}</td>
                  <td>
                    {row.template || "—"}
                    {row.trade ? ` · ${row.trade}` : ""}
                  </td>
                  <td>{row.visits}</td>
                  <td>
                    <span className={row.sales > 0 ? `${s.pill} ${s.pillGood}` : s.pill}>{row.sales}</span>
                  </td>
                  <td>{row.rate}%</td>
                  <td>{row.sources.map(x => `${x.name} (${x.count})`).join(", ") || "—"}</td>
                  <td>{when(row.lastSeen)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>

    <div className={s.card}>
      <h2 className={s.cardTitle}>Which groups worked</h2>
      {!report?.groups?.length ? (
        <p className={s.note}>Nothing to compare yet.</p>
      ) : (
        <div className={s.scroll}>
          <table className={s.table}>
            <thead>
              <tr>
                <th>Group</th>
                <th>Codes posted</th>
                <th>Visits</th>
                <th>Sales</th>
              </tr>
            </thead>
            <tbody>
              {report.groups.map(row => (
                <tr key={row.group}>
                  <td>{row.group}</td>
                  <td>{row.codes}</td>
                  <td>{row.visits}</td>
                  <td>{row.sales}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      <p className={s.note}>
        A visit is counted once per person, not once per page they look at. Sales are counted when the
        payment actually goes through.
      </p>
    </div>
  </>
)

export default AffiliateAdverts
