import * as React from "react"
import * as s from "./Tracked.module.css"

/**
 * Campaigns against each other — FCS-087.
 * ============================================================================
 * A plain SVG line per campaign over the same days. Drawn by hand rather than
 * with a charting library because it is one chart of a few short series, and
 * a library would be a few hundred kilobytes to draw a few polylines.
 *
 * ── THE AXIS STARTS AT ZERO ────────────────────────────────────────────────
 * Comparing two campaigns by the height of their lines only means anything if
 * the baseline is the same and honest. A truncated axis makes twelve scans
 * look like a boom next to nine.
 *
 * ── EVERY LINE IS LABELLED WITH ITS TOTAL ──────────────────────────────────
 * Colour alone is not enough to tell lines apart for everybody, and a chart
 * with a legend nobody can match to a line is decoration. The legend is a row
 * of toggles carrying name and total, so it doubles as the table.
 */
const COLOURS = ["#1668e8", "#d97706", "#0f766e", "#be123c", "#6b21a8", "#166534", "#0d1726"]

const W = 640
const H = 260
const PAD = { l: 38, r: 14, t: 14, b: 30 }

const niceMax = n => {
  if (n <= 4) return 4
  const step = Math.pow(10, Math.floor(Math.log10(n)))
  return Math.ceil(n / step) * step
}

const LineChart = ({ dates, series }) => {
  const [hidden, setHidden] = React.useState({})
  const shown = series.filter(line => !hidden[line.id])

  const peak = Math.max(0, ...shown.flatMap(line => line.counts))
  const top = niceMax(peak)
  const innerW = W - PAD.l - PAD.r
  const innerH = H - PAD.t - PAD.b
  const x = i => PAD.l + (dates.length <= 1 ? 0 : (i / (dates.length - 1)) * innerW)
  const y = v => PAD.t + innerH - (v / top) * innerH

  const ticks = [0, 0.25, 0.5, 0.75, 1].map(f => Math.round(top * f))
  const label = i => {
    const d = new Date(`${dates[i]}T00:00:00Z`)
    return d.toLocaleDateString(undefined, { month: "short", day: "numeric", timeZone: "UTC" })
  }
  const labelAt = [0, Math.floor((dates.length - 1) / 2), dates.length - 1]

  return (
    <div>
      <svg
        viewBox={`0 0 ${W} ${H}`}
        className={s.chart}
        role="img"
        aria-label="Scans per day for each campaign"
      >
        {ticks.map(t => (
          <g key={t}>
            <line x1={PAD.l} x2={W - PAD.r} y1={y(t)} y2={y(t)} stroke="#e8ecf1" />
            <text x={PAD.l - 8} y={y(t) + 4} textAnchor="end" fontSize="11" fill="#8496a8">
              {t}
            </text>
          </g>
        ))}
        {labelAt.map(i => (
          <text
            key={i}
            x={x(i)}
            y={H - 8}
            fontSize="11"
            fill="#8496a8"
            textAnchor={i === 0 ? "start" : i === dates.length - 1 ? "end" : "middle"}
          >
            {label(i)}
          </text>
        ))}
        {series.map((line, n) =>
          hidden[line.id] ? null : (
            <polyline
              key={line.id}
              fill="none"
              stroke={COLOURS[n % COLOURS.length]}
              strokeWidth="2.2"
              strokeLinejoin="round"
              strokeLinecap="round"
              points={line.counts.map((v, i) => `${x(i)},${y(v)}`).join(" ")}
            />
          )
        )}
      </svg>

      <div className={s.legend}>
        {series.map((line, n) => (
          <button
            key={line.id}
            type="button"
            className={s.legendItem}
            data-off={hidden[line.id] ? "true" : undefined}
            aria-pressed={!hidden[line.id]}
            onClick={() => setHidden(h => ({ ...h, [line.id]: !h[line.id] }))}
          >
            <span className={s.dot} style={{ background: COLOURS[n % COLOURS.length] }} />
            {line.name}
            <strong>{line.total}</strong>
          </button>
        ))}
      </div>
    </div>
  )
}

export default LineChart
